/**
 * Return a fibonacci sequence as an array.
 *
 * @param n
 * @return {number[]}
 */function fibonacci(n) {
  const fibSequence = [1];

  let currentValue = 1;
  let previousValue = 0;

  if (n === 1) {
    return fibSequence;
