    const sa = slope(p, a);
    const sb = slope(p, b);
    [[sa, a], [sb, b]].forEach(e => {
      const el = memo.get(e[0]);
      if (!el || dist(p, el) < dist(p, e[1])) {
        memo.set(e[0], e[1]);
      }
    });
    return sa - sb;
