        {
            for (let x = 0; x < 8; x++)
            {
                if (x === 0 && y === 0)
                {
                    continue;
                }
    
                const tx = x * 100;
                const ty = y * 150;
    
                this.cameras.add(tx, ty, 100, 150, false, 'Cam' + i);
    
                i++;
    
