        graphics.fillStyle(color, alpha);

        graphics.fillCircle(400, 300, 256);

        graphics.setBlendMode(modeIndex);

        //  zero, one, one, zero, add

        //  Create the 4 select lists

        var srcRGB = $('<select>').attr('id', 'srcRGB').data('idx', 0).appendTo('body');
