        text.enableFilters();
        text.filters.internal.add(wipe);
        wipe.setRevealEffect();
        wipe.setLeftToRight();

        this.tweens.add({
            targets: wipe,
            progress: 1,
            hold: 500,
            duration: 3000,
            repeat: -1,
            onRepeat: () => {

                line++;

                if (line === message.length)
