            targets: pixelate,
            amount: -1,
            duration: 10000,
            yoyo: true,
            loop: -1
        });

        this.tweens.add({
            targets: blur,
            strength: 0,
            duration: 10000,
            yoyo: true,
            loop: -1
        });
