        this.tweens.add({
            targets: this.container1,
            x: 400,
            duration: 6000,
            yoyo: true,
            repeat: -1
        });

        this.tweens.add({
            targets: this.container2,
            x: 400,
            duration: 6000,
            yoyo: true,
            repeat: -1
        });

        this.tweens.add({
            targets: this.image,
            scaleX: 2,
            scaleY: 2,
            duration: 6000,
            yoyo: true,
