        this.text2 = this.add.text(500, 10, '', { font: '16px Courier', fill: '#00ff00' });

        this.tempMatrix = new Phaser.GameObjects.Components.TransformMatrix();
        this.tempParentMatrix = new Phaser.GameObjects.Components.TransformMatrix();
    }

    update ()
