            `y: ${d.translateY}`,
            `sx: ${d.scaleX}`,
            `sy: ${d.scaleY}`,
            `r: ${Phaser.Math.RadToDeg(d.rotation)}`
        ]);

        const bounds = this.image.getBounds();

        this.graphics.clear();

        this.graphics.lineStyle(1, 0x00ff00, 1);

        this.graphics.strokeRect(d.translateX, d.translateY, bounds.width, bounds.height);
