        const intensity = 6;
        let x = radius;
        let y = 0;

        //  To change the total number of lights see the Game Config object
        const maxLights = 20;

        //  Create a bunch of lights
        for (let i = 0; i < maxLights; i++)
        {
            const color = hsv[i * 10].color;

            const light = this.lights.addLight(x, y, radius, color, intensity);

            this.tweens.add({
