                y: 600,
                yoyo: true,
                repeat: -1,
                ease: 'Sine.easeInOut',
                duration: 2000,
                delay: i * 100
            });

            x += radius * 2;

            if (x > 800)
            {
                x = radius;
                y += radius;
            }
        }
    }
}

