        this.trees.y -= 200;
        sprite.y -= 200;

        // Capture the current frame.
        this.cameras.main.forceComposite = true;
        this.add.captureFrame('capture');

        // Create animated normal map for ripples.
        this.noise = this.add.noisecell4d({
            noiseCells: [ 4, 32, 4, 4 ],
