            this.noise.noiseOffset[0] - 6 / 800, // Match background scroll.
            0,
            Math.cos(this.noise.noiseOffset[0] / 10), // Evolve noise field.
            Math.sin(this.noise.noiseOffset[0] / 10),
        ];
    }
