        this.tween.updateTo('x', this.player.x, true);
        this.tween.updateTo('y', this.player.y, true);

        this.trail.setAlpha(100 / (dist + 0.001));
        this.trail.setTint(dist | 0xff0000);

        this.rt.draw(this.trail).render();
    }
