const float layersF = float(layers);
for (int i = 0; i < layers; i++)
{
    float layer = cloudyNoise(vec2(outTexCoord.x, 1. - outTexCoord.y + float(layers - i) * 0.002));
    sum += layer;
    float layerBrightness = float(i) / (layersF - 1.0);
    col += layer * layerBrightness;
