// Normalize the sum to the range [0, 1].
sum /= layersF;
col /= layersF;

float alpha = 1.0 - (0.55 - sum) * 16.0;
alpha = clamp(alpha, 0.0, 1.0);
alpha *= outTexCoord.y * 0.5 + 0.5;

// Brighten the color.
col = (col - 0.26) * 12.0;

// Reduce color by density.
col *= 1.3 - sum * 0.8;

fragColor = vec4(vec3(col * alpha), alpha) * tint;
