    {
        this.position += this.perpSlope;

        this.position = Phaser.Math.Clamp(this.position, 0, 250);

        const normal = Phaser.Geom.Line.GetNormal(this.line);

        const midPoint = Phaser.Geom.Line.GetMidPoint(this.line);

