        console.log('start');

        var eventEmitter = this.game.events;

        eventEmitter.on('step', this.update, this);
    }

    stop ()
    {
        console.log('stop');

        var eventEmitter = this.game.events;

        eventEmitter.off('step', this.update);
    }

