        p.xzy = vec3(1.3,0.999,0.7)*(abs((abs(p)/dot(p,p)-vec3(1.0,1.0,cos(uTime * 0.2)*0.5))));
    }

    gl_FragColor.rgb = texture.rgb * p;
    gl_FragColor.a = texture.a;
}
`;

