        crystalball.enableFilters();
        const glowFX = crystalball.filters.internal.addGlow();

        const emitter = this.add.particles(400, 300, 'flares', {
            frame: 'white',
            blendMode: 'ADD',
            lifespan: 1200,
            gravityY: -100,
