    {
        this.bullet1.x += this.speed * delta;

        if (this.bullet1.x > 800)
        {
            this.bullet1.x = -100;
        }
    }

    //  Fixed at 30fps, regardless of monitor speed
    steppedUpdate (time, delta)
    {
        this.bullet2.x += this.speed * delta;

        if (this.bullet2.x > 800)
        {
            this.bullet2.x = -100;
        }
    }
}

