class Inventory { constructor(){this.goods=new Map();} add(id,q){this.goods.set(id,this.count(id)+q);} remove(id,q){if(this.count(id)<q)return false;this.goods.set(id,this.count(id)-q);return true;} count(id){return this.goods.get(id)||0;} }
class Market {
  constructor(base){this.base=base;this.stock=new Map();}
  setStock(id,u){this.stock.set(id,u);} units(id){const u=this.stock.get(id);return u==null?50:u;}
  price(id){const base=this.base[id]||1; return Math.round(base * (50 / Math.max(1, this.units(id)))); }
}
class Store {
  constructor(w,m,i){this.wallet=w;this.market=m;this.inv=i;this.tax=0.1;}
  buy(id,q){const cost=this.market.price(id)*q;const paid=Math.round(cost*(1+this.tax)); if(!this.wallet.debit(paid))return {ok:false,paid}; this.inv.add(id,q); this.market.setStock(id,this.market.units(id)-q); return {ok:true,paid};}
  sell(id,q){if(!this.inv.remove(id,q))return {ok:false}; const gain=this.market.price(id)*q; this.wallet.credit(gain); this.market.setStock(id,this.market.units(id)+q); return {ok:true,gain};}
}
const wallet=new Wallet(100000), market=new Market({'herb':6}); market.setStock('herb',50);
const inv=new Inventory(), store=new Store(wallet,market,inv);
const start=wallet.balance, before=market.price('herb');
const buy=store.buy('herb',4);
assert(buy.ok, 'purchase succeeds when affordable');
assert(wallet.balance===start-buy.paid, 'wallet debited by exactly the amount paid');
assert(inv.count('herb')===4, 'inventory received the goods');
assert(market.price('herb')>=before, 'price rises as stock falls');
const sell=store.sell('herb',2);
assert(sell.ok && inv.count('herb')===2, 'selling returns goods to the market');
assert(wallet.balance>start-buy.paid, 'wallet credited from the sale');
console.log('gen economy fantasy/taxed OK');
```

