class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  hasItem(item, quantity) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.hasItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    if (!this.canCraft(recipeName)) return false;

    const recipe = this.recipes.find(r => r.getName() === recipeName);
    const ingredients = recipe.getIngredients();

    for (const [item, quantity] of Object.entries(ingredients)) {
      this.inventory.removeItem(item, quantity);
    }

    // For demonstration, we'll add the crafted item to the inventory
    this.inventory.addItem(recipeName, 1);
    return true;
  }

  listRecipes() {
    return this.recipes.map(recipe => recipe.getName());
  }
}

// Demo
const inventory = new Inventory();
inventory.addItem('wood', 10);
inventory.addItem('metal', 5);

const recipes = [
  new Recipe('sword', { wood: 3, metal: 1 }),
  new Recipe('shield', { wood: 4 })
];

const crafting = new Crafting(inventory, recipes);

console.log('Available recipes:', crafting.listRecipes());
console.log('Can craft sword:', crafting.canCraft('sword'));
console.log('Crafting sword:', crafting.craft('sword'));
console.log('Inventory after crafting sword:', inventory.getItems());
console.log('Can craft shield:', crafting.canCraft('shield'));
console.log('Crafting shield:', crafting.craft('shield'));
console.log('Inventory after crafting shield:', inventory.getItems());
