// Define the EventBus class to handle communication between systems
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Define the Trade system class
class Trade {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceTrade', this.handleTrade.bind(this));
  }

  handleTrade(tradeData) {
    console.log(`Trade processed: ${tradeData.resource} from ${tradeData.sender} to ${tradeData.receiver}`);
    this.eventBus.emit('reputationUpdate', { entity: tradeData.receiver, points: 1 });
  }
}

// Define the Reputation system class
class Reputation {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.reputations = {};
    this.eventBus.subscribe('reputationUpdate', this.updateReputation.bind(this));
  }

  updateReputation(updateData) {
    const { entity, points } = updateData;
    this.reputations[entity] = (this.reputations[entity] || 0) + points;
    console.log(`Reputation updated for ${entity}: ${this.reputations[entity]}`);
    if (this.reputations[entity] >= 10) {
      this.eventBus.emit('factionChange', { entity, newFaction: 'Allies' });
    }
  }
}

// Define the Faction system class
class Faction {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.factions = {};
    this.eventBus.subscribe('factionChange', this.changeFaction.bind(this));
  }

  changeFaction(changeData) {
    const { entity, newFaction } = changeData;
    this.factions[entity] = newFaction;
    console.log(`Faction changed for ${entity}: ${newFaction}`);
  }
}

// Run the demo
const eventBus = new EventBus();
const tradeSystem = new Trade(eventBus);
const reputationSystem = new Reputation(eventBus);
const factionSystem = new Faction(eventBus);

// Simulate a trade event
eventBus.emit('resourceTrade', { resource: 'Iron', sender: 'TraderA', receiver: 'Player1' });

// Simulate another trade event
eventBus.emit('resourceTrade', { resource: 'Gold', sender: 'TraderB', receiver: 'Player1' });

// Output:
// Trade processed: Iron from TraderA to Player1
// Reputation updated for Player1: 1
// Trade processed: Gold from TraderB to Player1
// Reputation updated for Player1: 2
// Faction changed for Player1: Allies
