// Bank System
class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

// Market System
class Market {
  constructor(prices) {
    this.prices = prices; // prices is an object mapping item names to their prices
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return true;
    }
    return false;
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price) {
      bank.deposit(price);
      return true;
    }
    return false;
  }

