  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }

  buyItem(item, quantity) {
    const price = this.prices[item];
    if (price && this.inventory.getItemCount(item) >= quantity) {
