      'greeting': "Hello, brave adventurer!",
      'questStart': "I need your help! Do you accept the quest?",
      'questComplete': "Thank you for completing the quest!",
    };

    if (dialogueKey === 'questStart' && this.flags.get('questAccepted')) {
      return "You have already accepted the quest.";
    }

    return dialogues[dialogueKey] || "I don't have anything to say.";
  }
