class Loot {
  constructor(name, rarity) {
    this.name = name;
    this.rarity = rarity;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      'common': { probability: 0.7, priceRange: { min: 10, max: 20 } },
      'uncommon': { probability: 0.2, priceRange: { min: 30, max: 50 } },
      'rare': { probability: 0.08, priceRange: { min: 60, max: 100 } },
      'epic': { probability: 0.01, priceRange: { min: 150, max: 300 } },
      'legendary': { probability: 0.01, priceRange: { min: 500, max: 1000 } }
    };
  }

  generateLoot() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const rarity in this.table) {
      cumulativeProbability += this.table[rarity].probability;
      if (rand < cumulativeProbability) {
        const price = Math.floor(Math.random() * (this.table[rarity].priceRange.max - this.table[rarity].priceRange.min + 1)) + this.table[rarity].priceRange.min;
        return new Loot(`Loot-${rarity}`, rarity);
      }
    }

    return new Loot('Unknown', 'common');
  }
}

