class TradeSystem {
  constructor() {
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  trade(resource, amount, price) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      this.resources['gold'] += price;
      return true;
    }
    return false;
  }

  getResources() {
    return { ...this.resources };
  }
}

class ReputationSystem {
  constructor() {
    this.reputation = 50; // Neutral starting reputation
  }

  changeReputation(change) {
    this.reputation += change;
    if (this.reputation < 0) this.reputation = 0;
    if (this.reputation > 100) this.reputation = 100;
    return this.reputation;
  }

  getReputation() {
    return this.reputation;
  }
}

class FactionSystem {
  constructor() {
    this.factionStanding = { 'Guild': 50, 'Cult': 50, 'Legion': 50 };
  }

  changeFactionStanding(faction, change) {
    if (this.factionStanding[faction] !== undefined) {
      this.factionStanding[faction] += change;
      if (this.factionStanding[faction] < 0) this.factionStanding[faction] = 0;
      if (this.factionStanding[faction] > 100) this.factionStanding[faction] = 100;
    }
    return this.factionStanding[faction];
  }

  getFactionStanding(faction) {
    return this.factionStanding[faction] || 0;
  }
}

class GameCoordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  performTrade(resource, amount, price) {
    const success = this.tradeSystem.trade(resource, amount, price);
    if (success) {
      this.reputationSystem.changeReputation(1);
      this.factionSystem.changeFactionStanding('Guild', 2);
    } else {
      this.reputationSystem.changeReputation(-1);
      this.factionSystem.changeFactionStanding('Cult', -2);
    }
    return success;
  }

  getResources() {
    return this.tradeSystem.getResources();
  }

  getReputation() {
    return this.reputationSystem.getReputation();
  }

  getFactionStanding(faction) {
    return this.factionSystem.getFactionStanding(faction);
  }
}

