    this.rarityLevels = rarityLevels;
  }

  getRandomRarity() {
    const totalWeight = Object.values(this.rarityLevels).reduce((acc, weight) => acc + weight, 0);
    const random = Math.random() * totalWeight;
    let cumulativeWeight = 0;

    for (const [rarity, weight] of Object.entries(this.rarityLevels)) {
      cumulativeWeight += weight;
      if (random < cumulativeWeight) {
        return rarity;
      }
    }

    return null; // This should never happen if weights are correctly set
  }
}

