    return this.items;
  }

  getPrice(item) {
    return this.items[item] || null;
  }

  purchase(item, economy) {
    const price = this.getPrice(item);
    if (price !== null && economy.getBalance() >= price) {
      economy.withdraw(price);
      console.log(`Purchased ${item} for ${price}.`);
      return true;
    } else {
      console.log(`Purchase of ${item} failed. Insufficient funds or item does not exist.`);
      return false;
    }
  }
