class Economy {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
        this.balance = 1000; // Initial balance for demonstration
    }

    debit(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }

    getPrice(item) {
        return this.pricing.getPrice(item);
    }

    getDemand(item) {
        return this.demand.getDemand(item);
    }
