class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, quantity) {
        const price = this.economy.getPrice(item);
        const demand = this.economy.getDemand(item);

        if (demand < quantity) {
            console.log(`Not enough demand for ${item}`);
            return false;
        }

        const totalCost = price * quantity;
        if (this.economy.debit(totalCost)) {
            this.inventory.addItem(item, quantity);
            console.log(`Purchased ${quantity} ${item}(s) for ${totalCost}`);
            return true;
        } else {
            console.log(`Insufficient balance to purchase ${quantity} ${item}(s)`);
            return false;
        }
    }
}

