    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Recipe {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  getIngredients(recipeName) {
    return this.recipes[recipeName];
  }

  hasRecipe(recipeName) {
    return this.recipes.hasOwnProperty(recipeName);
  }
}

class Crafting {
  constructor(inventory, recipe) {
    this.inventory = inventory;
    this.recipe = recipe;
  }

  canCraft(recipeName) {
    const ingredients = this.recipe.getIngredients(recipeName);
    if (!ingredients) return false;
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.removeItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    if (this.canCraft(recipeName)) {
      console.log(`Crafted ${recipeName}`);
      return true;
    }
    console.log(`Cannot craft ${recipeName}`);
    return false;
  }
}

