class Resource {
  constructor() {
    this.resources = {
      wood: 100,
      stone: 100,
      gold: 50
    };
  }

  hasResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      if (this.resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      this.resources[resource] -= amount;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Economy {
  constructor() {
    this.buildings = {
      house: 0,
      farm: 0,
      mine: 0
    };
  }

  addBuilding(type) {
    if (this.buildings[type]) {
      this.buildings[type]++;
    } else {
      this.buildings[type] = 1;
    }
  }

  getBuildings() {
    return { ...this.buildings };
  }
}

