class EventBus {
  constructor() {
    this.events = {};
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('gamePurchased', this.updatePricing.bind(this));
  }

  updatePricing(game) {
    console.log(`Updating price for ${game.name}`);
    game.price = game.basePrice * 0.9; // 10% discount after purchase
    this.eventBus.emit('priceUpdated', game);
  }

  setBasePrice(game, newPrice) {
    console.log(`Setting base price for ${game.name} to ${newPrice}`);
    game.basePrice = newPrice;
    this.eventBus.emit('priceUpdated', game);
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceUpdated', this.adjustDemand.bind(this));
  }

  adjustDemand(game) {
    console.log(`Adjusting demand for ${game.name}`);
    if (game.price < game.basePrice * 0.9) {
      game.demand = 'high';
    } else {
      game.demand = 'low';
    }
    this.eventBus.emit('demandChanged', game);
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demandChanged', this.updateStock.bind(this));
  }

  purchaseGame(game) {
    console.log(`Purchasing ${game.name}`);
    game.stock--;
    this.eventBus.emit('gamePurchased', game);
  }

  restockGame(game, quantity) {
    console.log(`Restocking ${game.name} by ${quantity}`);
    game.stock += quantity;
  }

  updateStock(game) {
    console.log(`Updating stock for ${game.name}`);
    if (game.demand === 'high' && game.stock < 10) {
      this.restockGame(game, 50);
    }
  }
}

