    this._balance = initialBalance;
  }

  get balance() {
    return this._balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this._balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this._balance >= amount) {
      this._balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor() {
    this._items = new Map();
  }

  addItem(itemName, price) {
    this._items.set(itemName, price);
  }

  getItemPrice(itemName) {
    return this._items.get(itemName) || null;
  }

  hasItem(itemName) {
    return this._items.has(itemName);
  }
}

class Inventory {
  constructor() {
    this._items = new Map();
  }

  addItem(itemName, quantity) {
    if (quantity > 0) {
      this._items.set(itemName, (this._items.get(itemName) || 0) + quantity);
      return true;
    }
    return false;
  }

  getItemCount(itemName) {
    return this._items.get(itemName) || 0;
  }

  removeItem(itemName, quantity) {
    if (quantity > 0 && this._items.has(itemName) && this._items.get(itemName) >= quantity) {
      this._items.set(itemName, this._items.get(itemName) - quantity);
      return true;
    }
    return false;
  }
}

