class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return { ...this.ingredients };
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasIngredients(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe instances
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;
    return this.inventory.hasIngredients(recipe.getIngredients());
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe || !this.inventory.hasIngredients(recipe.getIngredients())) {
      return false;
    }
    for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
      this.inventory.removeItem(item, quantity);
    }
    // For simplicity, we'll assume crafting produces 1 of the recipe name
    this.inventory.addItem(recipe.getName(), 1);
    return true;
  }

  getRecipes() {
    return this.recipes.map(recipe => recipe.getName());
  }
}

