class RarityTable {
  constructor() {
    this.table = {
      common: 70,
      uncommon: 20,
      rare: 8,
      epic: 2
    };
  }

  getRandomLoot() {
    const roll = Math.random() * 100;
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return this.createLoot(rarity);
      }
    }
    return null;
  }

  createLoot(rarity) {
    const baseValues = {
      common: 10,
      uncommon: 50,
      rare: 100,
      epic: 200
    };
    const value = baseValues[rarity] + Math.floor(Math.random() * 50);
    return new Loot(`${rarity} Item`, value);
  }
}

