class CombatSystem {
  constructor() {
    this.attacks = [];
  }

  registerAttack(name, damage) {
    this.attacks[name] = damage;
  }

  performAttack(attacker, defender, attackName) {
    const damage = this.attacks[attackName];
    if (damage) {
      console.log(`${attacker} attacks ${defender} with ${attackName}, dealing ${damage} damage.`);
      return damage;
    } else {
      console.log(`${attacker} attempts to use ${attackName}, but it's not a known attack.`);
      return 0;
    }
  }
}

class HealthSystem {
  constructor() {
    this.healths = {};
  }

  setHealth(entity, health) {
    this.healths[entity] = health;
  }

  getHealth(entity) {
    return this.healths[entity] || 0;
  }

  applyDamage(entity, damage) {
    const currentHealth = this.getHealth(entity);
    const newHealth = Math.max(currentHealth - damage, 0);
    this.setHealth(entity, newHealth);
    console.log(`${entity} takes ${damage} damage, health is now ${newHealth}.`);
  }
}

class LootSystem {
  constructor() {
    this.loots = {};
  }

  setLoot(entity, loot) {
    this.loots[entity] = loot;
  }

  getLoot(entity) {
    return this.loots[entity] || [];
  }

  addLoot(entity, item) {
    const currentLoot = this.getLoot(entity);
    currentLoot.push(item);
    this.setLoot(entity, currentLoot);
    console.log(`${entity} receives loot: ${item}.`);
  }
}

class GameCoordinator {
