    this.health.setHealth('Monster', 50);

    this.loot.setLoot('Player', []);
    this.loot.setLoot('Monster', ['Sword']);
  }

  startCombat() {
    const damage = this.combat.performAttack('Player', 'Monster', 'Punch');
    this.health.applyDamage('Monster', damage);

    const monsterDamage = this.combat.performAttack('Monster', 'Player', 'Kick');
    this.health.applyDamage('Player', monsterDamage);

    if (this.health.getHealth('Monster') === 0) {
