      this.balances[player] = 0;
    }
    if (this.balances[player] < amount) {
      throw new Error('Insufficient funds');
    }
    this.balances[player] -= amount;
  }

  credit(player, amount) {
    if (this.balances[player] === undefined) {
      this.balances[player] = 0;
    }
    this.balances[player] += amount;
