  getRandomItem() {
    if (this.items.length === 0) {
      throw new Error('No items available');
    }
    const randomIndex = Math.floor(Math.random() * this.items.length);
    return this.items[randomIndex];
  }
}

class RarityTable {
  constructor() {
    this.table = {};
  }

  addEntry(rarity, item, price) {
    if (!this.table[rarity]) {
      this.table[rarity] = [];
    }
    this.table[rarity].push({ item, price });
  }

  getRandomItem(rarity) {
    if (!this.table[rarity] || this.table[rarity].length === 0) {
      throw new Error(`No items available for rarity: ${rarity}`);
    }
    const randomIndex = Math.floor(Math.random() * this.table[rarity].length);
    return this.table[rarity][randomIndex];
  }
}

