class Pricing {
    constructor(basePrice) {
        this.basePrice = basePrice;
    }

    calculatePrice(quantity) {
        return this.basePrice * quantity;
    }
}

class Demand {
    constructor(baseDemand, priceSensitivity) {
        this.baseDemand = baseDemand;
        this.priceSensitivity = priceSensitivity;
    }

    calculateDemand(price) {
        return Math.max(0, this.baseDemand - (price * this.priceSensitivity));
    }
}

class Store {
    constructor(pricingSystem, demandSystem) {
        this.pricingSystem = pricingSystem;
        this.demandSystem = demandSystem;
    }

    sell(quantity) {
        const price = this.pricingSystem.calculatePrice(quantity);
        const demand = this.demandSystem.calculateDemand(price);
        const itemsSold = Math.min(quantity, demand);
        const revenue = itemsSold * price;
        return { itemsSold, revenue };
    }
}

