// Crafting System
class Crafting {
  constructor(inventory, recipe) {
    this.inventory = inventory;
    this.recipe = recipe;
  }

  canCraft(recipeId) {
    const recipe = this.recipe.getRecipe(recipeId);
    if (!recipe) return false;
    for (const [item, amount] of Object.entries(recipe)) {
      if (this.inventory.getItemAmount(item) < amount) {
        return false;
      }
    }
    return true;
  }

  craft(recipeId) {
    if (this.canCraft(recipeId)) {
      const recipe = this.recipe.getRecipe(recipeId);
      for (const [item, amount] of Object.entries(recipe)) {
        this.inventory.removeItem(item, amount);
      }
      const result = this.recipe.getResult(recipeId);
      this.inventory.addItem(result, 1);
      return true;
    }
    return false;
  }
}

// Recipe System
class Recipe {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipeId, ingredients, result) {
    this.recipes[recipeId] = { ingredients, result };
  }

  getRecipe(recipeId) {
    return this.recipes[recipeId]?.ingredients;
  }

  getResult(recipeId) {
    return this.recipes[recipeId]?.result;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount) {
    this.items[item] = (this.items[item] || 0) + amount;
  }

  removeItem(item, amount) {
    if (this.items[item] >= amount) {
      this.items[item] -= amount;
    }
  }

  getItemAmount(item) {
    return this.items[item] || 0;
  }
}

