class Pricing {
  constructor() {
    this.basePrice = 10;
  }

  calculatePrice(quantity) {
    return this.basePrice * quantity;
  }

  setBasePrice(newPrice) {
    this.basePrice = newPrice;
  }
}

class Demand {
  constructor() {
    this.demandLevel = 0.5; // 0.5 means no change, < 0.5 means demand is down, > 0.5 means demand is up
  }

  adjustDemand(change) {
    this.demandLevel += change;
    if (this.demandLevel < 0) this.demandLevel = 0;
    if (this.demandLevel > 1) this.demandLevel = 1;
  }

  getDemandLevel() {
    return this.demandLevel;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    const demandLevel = this.demand.getDemandLevel();
    const effectiveQuantity = Math.round(quantity * demandLevel);
    const price = this.pricing.calculatePrice(effectiveQuantity);
    console.log(`Sold ${effectiveQuantity} items for $${price.toFixed(2)}`);
    return price;
  }

  updateBasePrice(newPrice) {
    this.pricing.setBasePrice(newPrice);
  }

  adjustDemand(change) {
    this.demand.adjustDemand(change);
  }
}

