    constructor() {
        this.skills = {};
    }

    addSkill(skillName, level = 1) {
        this.skills[skillName] = level;
    }

    getSkillLevel(skillName) {
        return this.skills[skillName] || 0;
    }

    levelUpSkill(skillName) {
        if (this.skills[skillName]) {
            this.skills[skillName]++;
        } else {
            this.skills[skillName] = 1;
        }
    }
}

class Experience {
    constructor() {
        this.experiencePoints = 0;
    }

    gainExperience(points) {
        this.experiencePoints += points;
    }

    getExperience() {
        return this.experiencePoints;
    }
}

class LevelUp {
    constructor() {
        this.levels = 0;
    }

    levelUp() {
        this.levels++;
    }

    getLevel() {
        return this.levels;
    }
}

class GameCoordinator {
    constructor() {
        this.skillSystem = new Skill();
        this.experienceSystem = new Experience();
        this.levelUpSystem = new LevelUp();
    }

    addSkill(skillName) {
        this.skillSystem.addSkill(skillName);
    }

    gainExperience(points) {
        this.experienceSystem.gainExperience(points);
        this.checkLevelUp();
    }

    levelUpSkill(skillName) {
        this.skillSystem.levelUpSkill(skillName);
    }

    checkLevelUp() {
        const experience = this.experienceSystem.getExperience();
        const requiredExperience = this.levelUpSystem.getLevel() * 1000; // Level up every 1000 experience points
        if (experience >= requiredExperience) {
            this.levelUpSystem.levelUp();
            console.log(`Level up! You are now level ${this.levelUpSystem.getLevel()}`);
        }
    }

    getSkillLevel(skillName) {
        return this.skillSystem.getSkillLevel(skillName);
    }

    getExperience() {
        return this.experienceSystem.getExperience();
    }

    getLevel() {
        return this.levelUpSystem.getLevel();
    }
}

