class Loot {
  constructor(itemName, rarity, value) {
    this.itemName = itemName;
    this.rarity = rarity;
    this.value = value;
  }

  getDetails() {
    return {
      itemName: this.itemName,
      rarity: this.rarity,
      value: this.value
    };
  }
}

class RarityTable {
  constructor() {
    this.table = {
      'Common': 0.7,
      'Uncommon': 0.2,
      'Rare': 0.08,
      'Epic': 0.01,
      'Legendary': 0.01
    };
  }

  getRandomRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (rand < cumulativeProbability) {
        return rarity;
      }
    }

    return 'Common'; // Fallback to common
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(loot) {
    this.items.push(loot);
  }

  getInventory() {
    return this.items.map(item => item.getDetails());
  }
}

class GameCoordinator {
  constructor() {
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  generateLoot() {
    const rarity = this.rarityTable.getRandomRarity();
    const itemName = `${rarity} Item`;
    const value = this.calculateValue(rarity);
    const loot = new Loot(itemName, rarity, value);
    return loot;
  }

  calculateValue(rarity) {
    const baseValue = {
      'Common': 10,
      'Uncommon': 50,
      'Rare': 200,
      'Epic': 800,
      'Legendary': 3000
    };
    return baseValue[rarity] || baseValue['Common'];
  }

  lootItem() {
    const loot = this.generateLoot();
    this.inventory.addItem(loot);
    console.log(`Looted: ${JSON.stringify(loot.getDetails())}`);
  }

  showInventory() {
    const inventoryDetails = this.inventory.getInventory();
    console.log('Inventory:');
    inventoryDetails.forEach(item => console.log(JSON.stringify(item)));
  }
}

// Demo
const coordinator = new GameCoordinator();
coordinator.lootItem();
coordinator.lootItem();
coordinator.showInventory();
