class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  addMoney(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  spendMoney(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(prices) {
    this.prices = prices; // { itemName: price }
  }

  getItemPrice(itemName) {
    return this.prices[itemName] || null;
  }

  canPurchase(wallet, itemName) {
    const price = this.getItemPrice(itemName);
    return price !== null && wallet.getBalance() >= price;
  }

  purchase(wallet, inventory, itemName) {
    const price = this.getItemPrice(itemName);
    if (this.canPurchase(wallet, itemName)) {
      wallet.spendMoney(price);
      inventory.addItem(itemName);
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  getItems() {
    return this.items;
  }

  addItem(itemName) {
    this.items.push(itemName);
  }

  hasItem(itemName) {
    return this.items.includes(itemName);
  }
}

