class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, ...args) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(...args));
        }
    }
}

class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        this.eventBus.emit('balanceUpdated', this.balance);
    }

    withdraw(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            this.eventBus.emit('balanceUpdated', this.balance);
        } else {
            console.log('Insufficient funds');
        }
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = { 'gold': 10, 'silver': 5 };
        this.eventBus.subscribe('buy', this.buy.bind(this));
    }

    buy(item, quantity) {
        if (this.prices[item]) {
            const totalCost = this.prices[item] * quantity;
            this.eventBus.emit('withdraw', totalCost);
        } else {
            console.log('Item not found');
        }
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};
        this.eventBus.subscribe('itemAcquired', this.addItem.bind(this));
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
        console.log(`Inventory updated: ${item} x ${this.items[item]}`);
    }
}

