    if (this.events[eventName]) {
      this.events[eventName].forEach(handler => handler(data));
    }
  }

  subscribe(eventName, handler) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(handler);
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseMade', this.handlePurchase.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}, new balance: ${this.balance}`);
  }

  handlePurchase(data) {
    const { cost } = data;
    if (this.balance >= cost) {
      this.balance -= cost;
      console.log(`Purchase of ${cost} successful, new balance: ${this.balance}`);
      this.eventBus.emit('purchaseConfirmed', { cost });
    } else {
      console.log(`Insufficient funds for purchase of ${cost}`);
    }
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: { cost: 20 },
      shield: { cost: 15 }
    };
  }

  purchaseItem(itemName) {
    const item = this.items[itemName];
    if (item) {
      console.log(`Attempting to purchase ${itemName} for ${item.cost}`);
      this.eventBus.emit('purchaseMade', item);
    } else {
      console.log(`Item ${itemName} not found`);
    }
  }
}

class Inventory {
