class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredient1: quantity, ingredient2: quantity, ... }
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item1: quantity, item2: quantity, ... }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasIngredients(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  listItems() {
    return this.items;
  }
}

class Crafting {
  constructor() {
    this.recipes = []; // Array of Recipe objects
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      return recipe;
    }
    return null;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && inventory.hasIngredients(recipe.ingredients)) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      return true;
    }
    return false;
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting();
  }

  setup() {
    // Adding some recipes
    this.crafting.addRecipe(new Recipe('Sword', { 'Iron': 5, 'Wood': 1 }));
    this.crafting.addRecipe(new Recipe('Shield', { 'Iron': 3, 'Leather': 2 }));

    // Adding some items to inventory
    this.inventory.addItem('Iron', 10);
    this.inventory.addItem('Wood', 5);
    this.inventory.addItem('Leather', 5);
  }

  craftItem(itemName) {
    const recipe = this.crafting.canCraft(itemName);
    if (recipe) {
      if (this.crafting.craft(itemName, this.inventory)) {
        console.log(`Crafted ${itemName}`);
      } else {
        console.log(`Not enough resources to craft ${itemName}`);
      }
    } else {
      console.log(`No recipe for ${itemName}`);
    }
  }

  checkInventory() {
    console.log('Inventory:', this.inventory.listItems());
  }
}

