class Economy {
  constructor() {
    this.prices = {
      wheat: 10,
      corn: 15,
      rice: 20
    };
    this.balance = 100;
  }

  getPrices() {
    return { ...this.prices };
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Farm {
  constructor() {
    this.crops = {
      wheat: 0,
      corn: 0,
      rice: 0
    };
  }

  plantCrop(crop, amount) {
    if (this.crops[crop] !== undefined) {
      this.crops[crop] += amount;
      return true;
    }
    return false;
  }

  getCrops() {
    return { ...this.crops };
  }
}

class Market {
  constructor(economy, farm) {
    this.economy = economy;
    this.farm = farm;
  }

  purchaseCrop(crop, amount) {
    const prices = this.economy.getPrices();
    const pricePerUnit = prices[crop];
    const totalCost = pricePerUnit * amount;

    if (this.economy.debit(totalCost)) {
      this.farm.plantCrop(crop, amount);
      console.log(`Purchased ${amount} ${crop} for ${totalCost}. New balance: ${this.economy.getBalance()}`);
      return true;
    }
    console.log(`Insufficient funds to purchase ${amount} ${crop}. Current balance: ${this.economy.getBalance()}`);
    return false;
  }
}

