class Quest {
  constructor() {
    this.activeQuests = [];
  }

  startQuest(quest) {
    this.activeQuests.push(quest);
    console.log(`Quest started: ${quest}`);
  }

  completeQuest(quest) {
    const index = this.activeQuests.indexOf(quest);
    if (index !== -1) {
      this.activeQuests.splice(index, 1);
      console.log(`Quest completed: ${quest}`);
      return true;
    }
    return false;
  }

  getActiveQuests() {
    return [...this.activeQuests];
  }
}

