class GameCoordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startAndCompleteQuest(questName, rewardItem, rewardQuantity) {
    this.questSystem.startQuest(questName);
    this.rewardSystem.addReward(questName, rewardItem);
    if (this.questSystem.completeQuest(questName)) {
      const reward = this.rewardSystem.getReward(questName);
      if (reward) {
        this.inventorySystem.addItem(reward, rewardQuantity);
      }
    }
  }

  checkInventory() {
