// Quest System
class Quest {
  constructor(flags) {
    this.flags = flags;
    this.quests = {};
  }

  addQuest(key, requirements, reward) {
    this.quests[key] = { requirements, reward };
  }

  canCompleteQuest(key) {
    const quest = this.quests[key];
    if (!quest) return false;
    return quest.requirements.every(req => this.flags.getFlag(req));
  }

  completeQuest(key) {
    const quest = this.quests[key];
    if (!quest || !this.canCompleteQuest(key)) return;
    console.log(`Quest completed: ${key}. Reward: ${quest.reward}`);
  }
}

