// Pricing System
class Pricing {
  constructor(pricingData) {
    this.pricingData = pricingData;
  }

  getBasePrice(product) {
    return this.pricingData[product] || 0;
  }

  applyDiscount(price, discount) {
    return price * (1 - discount);
  }
}

// Demand System
class Demand {
  constructor(demandData) {
    this.demandData = demandData;
  }

  getDemand(product) {
    return this.demandData[product] || 0;
  }

  getAdjustedDemand(product, price) {
    // Simple model: demand decreases linearly with price
    const baseDemand = this.getDemand(product);
    const priceFactor = 0.1; // 10% decrease per unit price
    return Math.max(0, baseDemand - price * priceFactor);
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct(product, discount = 0) {
    const basePrice = this.pricing.getBasePrice(product);
    const discountedPrice = this.pricing.applyDiscount(basePrice, discount);
    const adjustedDemand = this.demand.getAdjustedDemand(product, discountedPrice);
    return { discountedPrice, adjustedDemand };
  }
}

// Demo
const pricingData = {
  apple: 1.0,
  banana: 0.5,
  orange: 0.75
};

const demandData = {
  apple: 100,
  banana: 150,
