class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.gainSkill.bind(this));
  }

  gainSkill(data) {
    const { level } = data;
    if (!this.skills[level]) {
      this.skills[level] = 0;
    }
    this.skills[level]++;
    console.log(`Skill at level ${level} gained. Total skills at this level: ${this.skills[level]}`);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('earnExperience', this.addExperience.bind(this));
  }

  addExperience(amount) {
    this.experiencePoints += amount;
    console.log(`Experience gained: ${amount}. Total experience: ${this.experiencePoints}`);
    if (this.experiencePoints >= 100) {
      this.levelUp();
    }
  }

  levelUp() {
    const level = Math.floor(this.experiencePoints / 100) + 1;
    console.log(`Leveled up to level ${level}`);
    this.eventBus.emit('levelUp', { level });
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.level = 1;
    this.eventBus.subscribe('levelUp', this.updateLevel.bind(this));
  }

