class Trade {
    constructor() {
        this.resources = { gold: 100, wood: 50, stone: 30 };
    }

    buy(resource, amount, pricePerUnit) {
        if (this.resources.gold >= pricePerUnit * amount) {
            this.resources.gold -= pricePerUnit * amount;
            this.resources[resource] = (this.resources[resource] || 0) + amount;
            return true;
        }
        return false;
    }

    sell(resource, amount, pricePerUnit) {
        if (this.resources[resource] >= amount) {
            this.resources[resource] -= amount;
            this.resources.gold += pricePerUnit * amount;
            return true;
        }
        return false;
    }

    getResources() {
        return { ...this.resources };
    }
}

class Reputation {
    constructor() {
        this.standing = 50; // Neutral standing
    }

    improve(amount) {
        this.standing = Math.min(100, this.standing + amount);
    }

    deteriorate(amount) {
        this.standing = Math.max(0, this.standing - amount);
    }

    getStanding() {
        return this.standing;
    }
}

class Faction {
    constructor() {
        this.allies = [];
        this.enemies = [];
    }

    declareWar(faction) {
        this.enemies.push(faction);
    }

    makePeace(faction) {
        this.enemies = this.enemies.filter(e => e !== faction);
        this.allies.push(faction);
    }

    getEnemies() {
        return [...this.enemies];
    }

    getAllies() {
        return [...this.allies];
    }
}

