        this.trade = new Trade();
        this.reputation = new Reputation();
        this.faction = new Faction();
    }

    tradeResources(resource, amount, pricePerUnit) {
        const success = this.trade.buy(resource, amount, pricePerUnit);
        if (success) {
            this.reputation.improve(5); // Good trade improves reputation
        } else {
            this.reputation.deteriorate(5); // Failed trade deteriorates reputation
        }
        return success;
    }

    sellResources(resource, amount, pricePerUnit) {
