        if (success) {
            this.reputation.improve(5); // Good trade improves reputation
        } else {
            this.reputation.deteriorate(5); // Failed trade deteriorates reputation
        }
        return success;
    }

    getTradeResources() {
        return this.trade.getResources();
    }

    getReputationStanding() {
        return this.reputation.getStanding();
    }

    declareWar(faction) {
        this.faction.declareWar(faction);
    }

    makePeace(faction) {
        this.faction.makePeace(faction);
    }

    getEnemies() {
        return this.faction.getEnemies();
    }

