class Building {
    constructor() {
        this.buildings = {};
    }

    build(name, type, cost) {
        if (this.canBuild(cost)) {
            this.buildings[name] = { type, cost };
            return true;
        }
        return false;
    }

    canBuild(cost) {
        // Assume economy system has a method `hasResources` to check resources
        return economy.hasResources(cost);
    }

