        return this.buildings[name];
    }
}

// Resource System
class Resource {
    constructor() {
        this.resources = { food: 100, wood: 100, gold: 100 };
    }

    addResource(type, amount) {
        if (this.resources[type] !== undefined) {
            this.resources[type] += amount;
        }
    }

    removeResource(type, amount) {
        if (this.resources[type] !== undefined && this.resources[type] >= amount) {
            this.resources[type] -= amount;
            return true;
        }
        return false;
    }

    hasResources(cost) {
        for (const [type, amount] of Object.entries(cost)) {
            if (this.resources[type] < amount) {
                return false;
            }
        }
        return true;
    }

    getResources() {
        return this.resources;
    }
}

// Economy System
class Economy {
    constructor() {
        this.resourceSystem = new Resource();
    }

    addResource(type, amount) {
        this.resourceSystem.addResource(type, amount);
    }

    removeResource(type, amount) {
        return this.resourceSystem.removeResource(type, amount);
    }

    hasResources(cost) {
        return this.resourceSystem.hasResources(cost);
    }

    getResources() {
        return this.resourceSystem.getResources();
    }
}

