    this.eventBus = eventBus;
    this.crops = [];
    this.eventBus.subscribe('cropGrown', this.onCropGrown.bind(this));
    this.eventBus.subscribe('buyCrop', this.onBuyCrop.bind(this));
  }

  growCrop(cropType) {
    const crop = new Crop(cropType);
    this.crops.push(crop);
    console.log(`Growing ${cropType} crop on the farm.`);
    crop.grow(() => {
      this.eventBus.emit('cropGrown', crop);
    });
  }

  onCropGrown(crop) {
    console.log(`${crop.type} crop has grown and is ready to sell.`);
  }

  onBuyCrop(data) {
    const { cropType, quantity } = data;
    const availableCrops = this.crops.filter(crop => crop.type === cropType && !crop.isSold);
    if (availableCrops.length >= quantity) {
      availableCrops.slice(0, quantity).forEach(crop => {
        crop.isSold = true;
        console.log(`Sold ${cropType} crop.`);
      });
      this.eventBus.emit('cropSold', { cropType, quantity });
    } else {
      console.log(`Not enough ${cropType} crops available to sell.`);
    }
  }
}

class Crop {
  constructor(type) {
    this.type = type;
    this.isSold = false;
  }

  grow(callback) {
    setTimeout(() => {
      callback();
    }, 2000); // Simulate growth time
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropGrown', this.onCropGrown.bind(this));
    this.eventBus.subscribe('cropSold', this.onCropSold.bind(this));
  }

  buyCrop(cropType, quantity) {
    this.eventBus.emit('buyCrop', { cropType, quantity });
  }

  onCropGrown(crop) {
    console.log(`Market received ${crop.type} crop from the farm.`);
  }

  onCropSold(data) {
    const { cropType, quantity } = data;
    console.log(`Market sold ${quantity} ${cropType} crops.`);
  }
}

// Demo
const eventBus = new EventBus();
const farm = new Farm(eventBus);
const market = new Market(eventBus);

farm.growCrop('wheat');
farm.growCrop('wheat');
market.buyCrop('wheat', 1);
setTimeout(() => {
  market.buyCrop('wheat', 1);
}, 3000);
