class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
            this.eventBus.emit('balanceChanged', { balance: this.balance });
        } else {
            console.log('Invalid deposit amount');
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
            this.eventBus.emit('balanceChanged', { balance: this.balance });
        } else {
            console.log('Invalid withdrawal amount');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = { apple: 1, banana: 2, orange: 1.5 };
        this.eventBus.subscribe('buy', this.buy.bind(this));
        this.eventBus.subscribe('balanceChanged', this.updateAffordability.bind(this));
    }

    buy(item, quantity) {
        const price = this.prices[item] || 0;
        if (price > 0) {
            const totalCost = price * quantity;
            this.eventBus.emit('withdraw', totalCost);
        } else {
            console.log('Item not available');
        }
    }

    updateAffordability(data) {
        const { balance } = data;
        Object.keys(this.prices).forEach(item => {
            const price = this.prices[item];
            console.log(`Can afford ${Math.floor(balance / price)} ${item}(s)`);
        });
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = { apple: 0, banana: 0, orange: 0 };
        this.eventBus.subscribe('buy', this.addItems.bind(this));
    }

    addItems(item, quantity) {
        if (this.items[item] !== undefined) {
            this.items[item] += quantity;
            console.log(`Added ${quantity} ${item}(s). Total: ${this.items[item]}`);
        } else {
            console.log('Item not recognized');
        }
    }

    getInventory() {
        return this.items;
    }
}

// Demo
const eventBus = new EventBus();
const bank = new Bank(eventBus);
const market = new Market(eventBus);
const inventory = new Inventory(eventBus);

bank.deposit(20);
market.buy('apple', 5);
market.buy('banana', 3);
inventory.getInventory();
