class Loot {
  constructor() {
    this.lootTable = {
      common: ['Potion', 'Coin', 'Stick'],
      uncommon: ['Ring', 'Cloth', 'Wand'],
      rare: ['Sword', 'Shield', 'Amulet'],
      epic: ['Staff', 'Armor', 'Necklace'],
      legendary: ['Dragon Scale', 'Ancient Tome', 'Heavenly Orb']
    };
  }

  generateLoot(rarity) {
    const lootList = this.lootTable[rarity] || [];
    if (lootList.length === 0) {
      return null;
    }
    const randomIndex = Math.floor(Math.random() * lootList.length);
    return lootList[randomIndex];
  }
}

class RarityTable {
  constructor() {
    this.rarityWeights = {
      common: 70,
      uncommon: 20,
      rare: 8,
      epic: 1,
      legendary: 1
    };
  }

  getRandomRarity() {
    const totalWeight = Object.values(this.rarityWeights).reduce((acc, weight) => acc + weight, 0);
    let randomWeight = Math.floor(Math.random() * totalWeight);
    for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
      randomWeight -= weight;
      if (randomWeight < 0) {
        return rarity;
      }
    }
    return 'common'; // Fallback to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  displayInventory() {
    console.log('Inventory:');
    for (const [item, count] of Object.entries(this.items)) {
      console.log(`${item}: ${count}`);
    }
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.lootSystem = new Loot();
    this.raritySystem = new RarityTable();
    this.inventorySystem = new Inventory();
  }

  generateAndCollectLoot() {
    const rarity = this.raritySystem.getRandomRarity();
    const loot = this.lootSystem.generateLoot(rarity);
    if (loot) {
      console.log(`Looted: ${loot} (Rarity: ${rarity})`);
      this.inventorySystem.addItem(loot);
    } else {
      console.log('No loot generated.');
    }
  }

  displayInventory() {
    this.inventorySystem.displayInventory();
  }
}

// Runnable demo
const game = new GameCoordinator();
game.generateAndCollectLoot();
game.generateAndCollectLoot();
game.generateAndCollectLoot();
game.displayInventory();
