// Economy class to manage currency
class Economy {
  constructor(initialBalance = 100) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

// Store class to manage purchases
class Store {
  constructor(prices) {
    this.prices = prices;
    this.inventory = {};
  }

  getPrices() {
    return { ...this.prices };
  }

  getInventory() {
    return { ...this.inventory };
  }

  purchase(item) {
    const price = this.prices[item];
    if (!price) {
      throw new Error("Item not available");
    }
    return price;
  }

  addToInventory(item) {
    if (this.inventory[item]) {
      this.inventory[item]++;
    } else {
      this.inventory[item] = 1;
    }
  }
}

// Farm class to manage crops
class Farm {
  constructor(store, economy) {
    this.store = store;
    this.economy = economy;
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  harvestCrops() {
    const harvestedCrops = this.crops;
    this.crops = [];
    return harvestedCrops;
  }

  sellCrops() {
    const cropsToSell = this.harvestCrops();
    cropsToSell.forEach(crop => {
      try {
        const price = this.store.purchase(crop);
        this.economy.debit(price);
        this.store.addToInventory(crop);
        console.log(`Sold ${crop} for ${price}`);
      } catch (error) {
        console.error(error.message);
      }
    });
  }
}

