class Quest {
  constructor(dialogueSystem, flagsSystem) {
    this.dialogueSystem = dialogueSystem;
    this.flagsSystem = flagsSystem;
    this.quests = {};
  }

  addQuest(id, dialogueId, completionFlag) {
    this.quests[id] = { dialogueId, completionFlag };
  }

  completeQuest(questId) {
    if (this.quests[questId]) {
      const { dialogueId, completionFlag } = this.quests[questId];
      console.log(this.dialogueSystem.getDialogue(dialogueId));
      this.flagsSystem.setFlag(completionFlag, true);
    } else {
      console.log('Quest not found');
    }
  }

  isQuestCompleted(questId) {
    const completionFlag = this.quests[questId]?.completionFlag;
    return completionFlag ? this.flagsSystem.getFlag(completionFlag) : false;
  }
}

