        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }

    getItems() {
        return Object.keys(this.prices);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(item, quantity = 1) {
        if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return { ...this.items };
    }
}

