class QuestSystem {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.quests = {};
        this.eventBus.subscribe('dialogueStarted', this.onDialogueStarted.bind(this));
    }

    addQuest(questName, requirements) {
        this.quests[questName] = { requirements, completed: false };
        console.log(`Quest ${questName} added with requirements:`, requirements);
    }

    completeQuest(questName) {
        if (this.quests[questName]) {
            this.quests[questName].completed = true;
            console.log(`Quest ${questName} completed.`);
            this.eventBus.emit('questCompleted', questName);
        } else {
            console.log(`Quest ${questName} not found.`);
        }
    }

    onDialogueStarted(character) {
        if (character === 'NPC') {
            this.checkAndCompleteQuests();
        }
    }

    checkAndCompleteQuests() {
        for (const questName in this.quests) {
            const quest = this.quests[questName];
            if (!quest.completed && this.areRequirementsMet(quest.requirements)) {
                this.completeQuest(questName);
            }
        }
    }

    areRequirementsMet(requirements) {
        for (const flag in requirements) {
            if (!flagsSystem.getFlag(flag) || flagsSystem.getFlag(flag) !== requirements[flag]) {
                return false;
            }
        }
        return true;
    }
}

