    this.inventory = inventory;
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  craft(name) {
    const recipe = this.recipes.find(r => r.name === name);
    if (recipe) {
      return recipe.craft(this.inventory);
    }
    return false;
  }

  canCraft(name) {
    const recipe = this.recipes.find(r => r.name === name);
    if (recipe) {
      return recipe.canCraft(this.inventory);
    }
    return false;
  }
}

