console.log('Can craft torch?', crafting.canCraft('torch')); // true
console.log('Craft torch:', crafting.craft('torch')); // true
console.log('Inventory after crafting torch:', inventory.items); // { wood: 9, stone: 4, stick: 0, torch: 1 }
