class Economy {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    addMoney(amount) {
        this.balance += amount;
    }

    subtractMoney(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return { ...this.items };
    }
}

class Store {
    constructor(economy, inventory, prices) {
        this.economy = economy;
        this.inventory = inventory;
        this.prices = prices;
    }

    buyItem(item, quantity = 1) {
        const price = this.prices[item] * quantity;
        if (this.economy.subtractMoney(price) && this.inventory.addItem(item, quantity)) {
            console.log(`Bought ${quantity} ${item}(s) for ${price}.`);
            return true;
        }
        console.log(`Failed to buy ${quantity} ${item}(s).`);
        return false;
    }

    sellItem(item, quantity = 1) {
        if (this.inventory.removeItem(item, quantity)) {
            const price = this.prices[item] * quantity;
            this.economy.addMoney(price);
            console.log(`Sold ${quantity} ${item}(s) for ${price}.`);
            return true;
        }
        console.log(`Failed to sell ${quantity} ${item}(s).`);
        return false;
    }

    getInventory() {
        return this.inventory.getInventory();
    }
}

// Demo
const economy = new Economy(100);
const inventory = new Inventory();
const prices = { apple: 10, banana: 5 };

const store = new Store(economy, inventory, prices);

console.log("Initial Balance:", economy.getBalance());
console.log("Initial Inventory:", inventory.getInventory());

store.buyItem("apple", 2); // Should succeed
store.buyItem("banana", 3); // Should succeed
store.buyItem("orange", 1); // Should fail (insufficient balance)

console.log("Balance after purchases:", economy.getBalance());
console.log("Inventory after purchases:", inventory.getInventory());

store.sellItem("apple", 1); // Should succeed
store.sellItem("banana", 2); // Should succeed
store.sellItem("orange", 1); // Should fail (no oranges in inventory)

console.log("Balance after sales:", economy.getBalance());
console.log("Inventory after sales:", inventory.getInventory());
