  constructor() {
    this.demands = {};
  }

  setDemand(product, demand) {
    this.demands[product] = demand;
  }

  getDemand(product) {
    return this.demands[product] || 0;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  calculateRevenue(product) {
    const price = this.pricing.getPrice(product);
    const demand = this.demand.getDemand(product);
    return price * demand;
  }

  getStockLevel(product) {
    // Assuming stock level is directly proportional to demand for simplicity
    return this.demand.getDemand(product);
  }
}

class Coordinator {
  constructor() {
    this.pricing = new Pricing();
    this.demand = new Demand();
    this.store = new Store(this.pricing, this.demand);
  }

  setupProduct(product, price, demand) {
    this.pricing.setPrice(product, price);
    this.demand.setDemand(product, demand);
  }

  report(product) {
    console.log(`Product: ${product}`);
    console.log(`Price: $${this.pricing.getPrice(product)}`);
    console.log(`Demand: ${this.demand.getDemand(product)}`);
    console.log(`Revenue: $${this.store.calculateRevenue(product)}`);
    console.log(`Stock Level: ${this.store.getStockLevel(product)}`);
  }
