class Experience {
  constructor(skill) {
    this.skill = skill;
    this.experiencePoints = 0;
  }

  addExperience(points) {
    this.experiencePoints += points;
    console.log(`Added ${points} experience points. Total: ${this.experiencePoints}`);

    if (this.experiencePoints >= this.skill.level * 100) {
      this.levelUp();
    }
  }

  levelUp() {
    this.experiencePoints -= this.skill.level * 100;
    this.skill.levelUp();
  }
}

class LevelUp {
  constructor(skill) {
    this.skill = skill;
  }

  canLevelUp() {
    return this.skill.experiencePoints >= this.skill.level * 100;
  }

  levelUp() {
    if (this.canLevelUp()) {
      this.skill.levelUp();
      this.skill.experiencePoints -= this.skill.level * 100;
      console.log(`Level up successful for ${this.skill.name}`);
    } else {
      console.log(`Not enough experience to level up ${this.skill.name}`);
    }
  }
}

