// Health System
class HealthSystem {
  constructor() {
    this.currentHealth = 100;
    this.maxHealth = 100;
  }

  takeDamage(damage) {
    this.currentHealth -= damage;
    if (this.currentHealth < 0) {
      this.currentHealth = 0;
    }
    console.log(`Health remaining: ${this.currentHealth}/${this.maxHealth}`);
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > this.maxHealth) {
      this.currentHealth = this.maxHealth;
    }
    console.log(`Healed by ${amount}. Health: ${this.currentHealth}/${this.maxHealth}`);
  }
}

// Loot System
class LootSystem {
  constructor() {
    this.lootPool = ['potion', 'sword', 'shield'];
  }

  dropLoot() {
    const loot = this.lootPool[Math.floor(Math.random() * this.lootPool.length)];
    console.log(`Dropped loot: ${loot}`);
    return loot;
  }

  useLoot(loot, target) {
    if (loot === 'potion') {
      target.heal(20);
    } else if (loot === 'sword') {
      target.attackPower += 5;
      console.log(`Attack power increased by 5. New attack power: ${target.attackPower}`);
    } else if (loot === 'shield') {
      target.currentHealth += 10;
      if (target.currentHealth > target.maxHealth) {
        target.currentHealth = target.maxHealth;
      }
      console.log(`Health increased by 10. New health: ${target.currentHealth}/${target.maxHealth}`);
    }
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.combatSystem = new CombatSystem();
    this.healthSystem = new HealthSystem();
    this.lootSystem = new LootSystem();
  }

  startCombat() {
    const damage = this.combatSystem.attack(this.healthSystem);
    this.healthSystem.takeDamage(damage);
    const loot = this.lootSystem.dropLoot();
    this.lootSystem.useLoot(loot, this.healthSystem);
  }

  receiveDamage(damage) {
    this.combatSystem.receiveDamage(damage);
    this.healthSystem.takeDamage(damage);
  }
}

