class Bank {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}, new balance is ${this.balance}`);
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds to withdraw ${amount}`);
            return false;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
        return true;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices) {
        this.prices = prices;
    }

    buy(item) {
        if (!this.prices[item]) {
            console.log(`Item ${item} is not available in the market`);
            return false;
        }
        return this.prices[item];
    }

    getPrices() {
        return { ...this.prices };
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (!this.items[item]) {
            this.items[item] = 0;
        }
        this.items[item] += quantity;
        console.log(`Added ${quantity} ${item}(s), current inventory:`, this.items);
    }

    removeItem(item, quantity) {
        if (!this.items[item] || this.items[item] < quantity) {
            console.log(`Insufficient ${item}(s) to remove`);
            return false;
        }
        this.items[item] -= quantity;
        console.log(`Removed ${quantity} ${item}(s), current inventory:`, this.items);
        return true;
    }

    getInventory() {
        return { ...this.items };
    }
}

