// Event Bus Implementation
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Combat System
class Combat {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('attack', this.handleAttack.bind(this));
    }

    handleAttack(data) {
        const { attacker, defender, damage } = data;
        console.log(`${attacker} attacks ${defender} for ${damage} damage.`);
        this.eventBus.emit('health-damage', { target: defender, amount: damage });
    }

    attack(attacker, defender, damage) {
        this.eventBus.emit('attack', { attacker, defender, damage });
    }
}

// Health System
class Health {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.healthMap = {};
        this.eventBus.subscribe('health-damage', this.handleDamage.bind(this));
        this.eventBus.subscribe('health-heal', this.handleHeal.bind(this));
    }

    handleDamage(data) {
        const { target, amount } = data;
        if (!this.healthMap[target]) {
            this.healthMap[target] = 100; // Default health
        }
        this.healthMap[target] -= amount;
        if (this.healthMap[target] <= 0) {
            console.log(`${target} has been defeated!`);
            this.eventBus.emit('defeat', { target });
        } else {
            console.log(`${target} has ${this.healthMap[target]} health remaining.`);
        }
    }

    handleHeal(data) {
        const { target, amount } = data;
        if (!this.healthMap[target]) {
            this.healthMap[target] = 0;
        }
        this.healthMap[target] += amount;
        console.log(`${target} has been healed by ${amount}, now has ${this.healthMap[target]} health.`);
    }

    heal(target, amount) {
        this.eventBus.emit('health-heal', { target, amount });
    }
}

// Loot System
class Loot {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('defeat', this.handleDefeat.bind(this));
    }

    handleDefeat(data) {
        const { target } = data;
        const loot = this.dropLoot();
        console.log(`${target} dropped ${loot}.`);
    }

    dropLoot() {
        const lootItems = ['potion', 'gold', 'weapon'];
        return lootItems[Math.floor(Math.random() * lootItems.length)];
    }
}

// Demo
const eventBus = new EventBus();
const combat = new Combat(eventBus);
const health = new Health(eventBus);
const loot = new Loot(eventBus);

// Simulate a battle
combat.attack('Hero', 'Monster', 30);
health.heal('Hero', 20);
combat.attack('Hero', 'Monster', 50);
health.heal('Hero', 10);
combat.attack('Hero', 'Monster', 80);
