class Economy {
  constructor() {
    this.balance = 0;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor() {
    this.items = {
      'apple': { price: 1, stock: 10 },
      'banana': { price: 2, stock: 5 },
      'orange': { price: 3, stock: 8 }
    };
  }

  getItemPrice(item) {
    return this.items[item]?.price || 0;
  }

  purchaseItem(item, economy) {
    const price = this.getItemPrice(item);
    if (price > 0 && economy.withdraw(price)) {
      this.items[item].stock -= 1;
      return true;
    }
    return false;
  }

  getStock(item) {
    return this.items[item]?.stock || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += 1;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

