    this.economy = new Economy();
    this.store = new Store();
    this.inventory = new Inventory();
  }

  depositMoney(amount) {
    if (this.economy.deposit(amount)) {
      console.log(`Deposited ${amount} units. New balance: ${this.economy.getBalance()}`);
    } else {
      console.log(`Failed to deposit ${amount} units.`);
    }
