    } else {
      console.log(`Failed to purchase ${item}.`);
    }
  }

  checkBalance() {
    console.log(`Current balance: ${this.economy.getBalance()}`);
  }

  checkInventory(item) {
    console.log(`Inventory of ${item}: ${this.inventory.getItemCount(item)}`);
  }
}

