class Hunger {
    constructor() {
        this.hungerLevel = 100; // Max hunger is 100
    }

    eat(amount) {
        this.hungerLevel = Math.max(0, this.hungerLevel - amount);
        console.log(`Ate ${amount}. Hunger is now ${this.hungerLevel}.`);
    }

    getHungerLevel() {
        return this.hungerLevel;
    }
}

class Energy {
    constructor() {
        this.energyLevel = 100; // Max energy is 100
    }

    rest(amount) {
        this.energyLevel = Math.min(100, this.energyLevel + amount);
        console.log(`Rested ${amount}. Energy is now ${this.energyLevel}.`);
    }

    consumeEnergy(amount) {
        this.energyLevel = Math.max(0, this.energyLevel - amount);
        console.log(`Consumed ${amount} energy. Energy is now ${this.energyLevel}.`);
    }

    getEnergyLevel() {
        return this.energyLevel;
    }
}

class Clock {
    constructor() {
        this.time = 0; // Time in hours
    }

    tick() {
        this.time++;
        console.log(`Time is now ${this.time} hours.`);
        return this.time;
    }

    getTime() {
        return this.time;
    }
}

class Coordinator {
    constructor() {
        this.hunger = new Hunger();
        this.energy = new Energy();
        this.clock = new Clock();
    }

    simulateDay() {
        console.log("Simulating a day...");
        while (this.clock.getTime() < 24) {
            const currentTime = this.clock.tick();

            // Random events during the day
            if (currentTime % 3 === 0) {
                this.hunger.eat(10);
            } else if (currentTime % 5 === 0) {
                this.energy.rest(10);
            } else {
                this.energy.consumeEnergy(5);
            }

            // Check for critical conditions
            if (this.hunger.getHungerLevel() <= 20) {
                console.log("Warning: Hunger is critically low!");
            }
            if (this.energy.getEnergyLevel() <= 20) {
                console.log("Warning: Energy is critically low!");
            }
        }
        console.log("Day simulation complete.");
    }
}

