      'Rare': 15,
      'Epic': 3,
      'Legendary': 2
    };
  }

  getRandomLoot() {
    const rarities = Object.keys(this.table);
    let total = 0;
    for (let rarity of rarities) {
      total += this.table[rarity];
    }

    let random = Math.floor(Math.random() * total);
    for (let rarity of rarities) {
      if (random < this.table[rarity]) {
        return new Loot(`Item-${rarity}`, rarity);
      }
      random -= this.table[rarity];
    }
  }
