class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item]) {
      if (this.items[item] >= quantity) {
        this.items[item] -= quantity;
        if (this.items[item] === 0) {
          delete this.items[item];
        }
        return true;
      }
    }
    return false;
  }

  hasItems(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe) {
      return this.inventory.hasItems(recipe.getIngredients());
    }
    return false;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe && this.canCraft(recipeName)) {
      for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
        this.inventory.removeItem(item, quantity);
      }
      console.log(`Crafted ${recipeName}`);
      return true;
    }
    console.log(`Cannot craft ${recipeName}`);
    return false;
  }
}

