// RarityTable class to determine item rarity and value
class RarityTable {
  constructor() {
    this.rarityMap = {
      common: { min: 1, max: 10 },
      rare: { min: 11, max: 50 },
      epic: { min: 51, max: 100 }
    };
  }

  generateLoot() {
    const roll = Math.floor(Math.random() * 100) + 1;
    let rarity, value;

    if (roll <= this.rarityMap.common.max) {
      rarity = "common";
      value = Math.floor(Math.random() * 5) + 1; // 1-5
    } else if (roll <= this.rarityMap.rare.max) {
      rarity = "rare";
      value = Math.floor(Math.random() * 10) + 6; // 6-15
    } else {
      rarity = "epic";
      value = Math.floor(Math.random() * 20) + 16; // 16-35
    }

    return new Loot(`Item-${rarity[0].toUpperCase() + rarity.slice(1)}`, value);
  }
}

