class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.level = 0;
    this.experience = 0;

    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  gainExperience(amount) {
    this.experience += amount;
    this.eventBus.emit('experienceGained', { amount });
  }

  onLevelUp(level) {
    console.log(`Skill leveled up to level ${level}`);
    // Reset experience after leveling up
    this.experience = 0;
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.requiredExperience = 100;
    this.currentExperience = 0;

    this.eventBus.subscribe('experienceGained', this.onExperienceGained.bind(this));
  }

  onExperienceGained(data) {
    this.currentExperience += data.amount;
    console.log(`Gained ${data.amount} experience. Total: ${this.currentExperience}`);

    if (this.currentExperience >= this.requiredExperience) {
      this.eventBus.emit('levelUp', { level: this.currentExperience / this.requiredExperience });
      this.currentExperience -= this.requiredExperience;
    }
  }
