if (game.buyFromMarket('apples', 3, 1)) {
  console.log('Purchase successful.');
} else {
  console.log('Purchase failed.');
}
game.report();

console.log('\nSelling 2 apples for $2 each:');
if (game.sellToMarket('apples', 2, 2)) {
  console.log('Sale successful.');
} else {
  console.log('Sale failed.');
}
game.report();
