class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Shop {
  constructor(wallet, inventory) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }

  buyItem(item, quantity = 1) {
    if (quantity > 0 && this.prices[item]) {
      const totalPrice = this.prices[item] * quantity;
      if (this.wallet.withdraw(totalPrice)) {
        this.inventory.addItem(item, quantity);
        return true;
      }
    }
    return false;
  }

  sellItem(item, quantity = 1) {
    if (quantity > 0 && this.inventory.removeItem(item, quantity)) {
      const totalPrice = this.prices[item] * quantity;
      this.wallet.deposit(totalPrice);
      return true;
    }
    return false;
  }
}

