class ResourceManager {
  constructor() {
    this.resources = {
      "Faction A": { gold: 100, wood: 50 },
      "Faction B": { gold: 80, wood: 70 },
      "Faction C": { gold: 120, wood: 30 }
    };
  }

  hasResource(faction, resource, amount) {
    return (this.resources[faction] && this.resources[faction][resource] >= amount);
  }

  transferResource(resource, amount, targetFaction) {
    if (this.hasResource("Faction A", resource, amount)) {
      this.resources["Faction A"][resource] -= amount;
      if (!this.resources[targetFaction]) {
        this.resources[targetFaction] = {};
      }
      this.resources[targetFaction][resource] = (this.resources[targetFaction][resource] || 0) + amount;
    }
  }
}

