class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;
    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.hasItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe || !this.canCraft(recipeName)) {
      return false;
    }
    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      this.inventory.removeItem(item, quantity);
    }
    this.inventory.addItem(recipe.getResult(), 1);
    return true;
  }

  listRecipes() {
    return this.recipes.map(recipe => recipe.getName());
  }
}

