  sellCrop(crop) {
    const index = this.crops.indexOf(crop);
    if (index !== -1) {
      this.crops.splice(index, 1);
      console.log(`Sold ${crop.name}`);
      this.eventBus.emit('cropSold', crop);
    }
  }
}

