// Pricing System
class Pricing {
    constructor() {
        this.basePrice = 10;
    }

    calculatePrice(quantity) {
        return this.basePrice * quantity;
    }
}

// Demand System
class Demand {
    constructor() {
        this.baseDemand = 100;
    }

    calculateDemand(price) {
        return Math.max(0, this.baseDemand - (price / 2));
    }
}

// Store System
class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
        this.stock = 50;
    }

    sell(quantity) {
        const price = this.pricing.calculatePrice(quantity);
        const availableDemand = this.demand.calculateDemand(price);

        const actualQuantity = Math.min(quantity, availableDemand, this.stock);
        this.stock -= actualQuantity;

        return {
            sold: actualQuantity,
            price: price,
            stockLeft: this.stock
        };
    }
}

// Coordinator
function runGame() {
    const pricingSystem = new Pricing();
    const demandSystem = new Demand();
    const storeSystem = new Store(pricingSystem, demandSystem);

    console.log("Initial Stock:", storeSystem.stock);

    const transaction1 = storeSystem.sell(10);
