class CraftingSystem {
    constructor(recipeSystem, inventorySystem) {
        this.recipeSystem = recipeSystem;
        this.inventorySystem = inventorySystem;
    }

    craftItem(itemName) {
        const recipe = this.recipeSystem.getRecipe(itemName);
        if (!recipe) {
            console.log(`No recipe found for ${itemName}`);
            return false;
        }

        const hasIngredients = recipe.ingredients.every(ingredient => {
            return this.inventorySystem.hasItem(ingredient, recipe.quantity);
        });

        if (!hasIngredients) {
            console.log(`Missing ingredients for ${itemName}`);
            return false;
        }

        recipe.ingredients.forEach(ingredient => {
            this.inventorySystem.removeItem(ingredient, recipe.quantity);
        });

        this.inventorySystem.addItem(itemName, 1);
        console.log(`Crafted ${itemName}`);
        return true;
    }
}

class RecipeSystem {
    constructor() {
        this.recipes = {};
    }

    addRecipe(itemName, ingredients, quantity) {
        this.recipes[itemName] = { ingredients, quantity };
    }

    getRecipe(itemName) {
        return this.recipes[itemName];
    }
}

class InventorySystem {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity) {
        if (this.items[itemName]) {
            this.items[itemName] += quantity;
        } else {
            this.items[itemName] = quantity;
        }
    }

    removeItem(itemName, quantity) {
        if (this.items[itemName] && this.items[itemName] >= quantity) {
            this.items[itemName] -= quantity;
            if (this.items[itemName] === 0) {
                delete this.items[itemName];
            }
        }
    }

    hasItem(itemName, quantity) {
        return this.items[itemName] && this.items[itemName] >= quantity;
    }

    getItemQuantity(itemName) {
        return this.items[itemName] || 0;
    }
}

