// Event Bus Implementation
class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, callback) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(callback);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(callback => callback(data));
        }
    }
}

// Building System
class Building {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.buildings = {};

        this.eventBus.subscribe('resourceCollected', this.onResourceCollected.bind(this));
    }

    build(type) {
        if (!this.buildings[type]) {
            this.buildings[type] = 0;
        }
        this.buildings[type]++;
        console.log(`Built ${type} building. Total: ${this.buildings[type]}`);
        this.eventBus.emit('buildingBuilt', { type });
    }

    onResourceCollected(data) {
        console.log(`Resource collected: ${data.amount} ${data.resource}`);
    }
}

// Resource System
class Resource {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.resources = {};

        this.eventBus.subscribe('buildingBuilt', this.onBuildingBuilt.bind(this));
    }

    collect(resource, amount) {
        if (!this.resources[resource]) {
            this.resources[resource] = 0;
        }
        this.resources[resource] += amount;
        console.log(`Collected ${amount} ${resource}. Total: ${this.resources[resource]}`);
        this.eventBus.emit('resourceCollected', { resource, amount });
    }

    onBuildingBuilt(data) {
        console.log(`New ${data.type} building built. Starting resource collection.`);
        this.collect('wood', 10); // Example resource collection
    }
}

// Economy System
class Economy {
