// Crafting System
class Crafting {
  constructor() {
    this.recipes = new Map();
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.name, recipe);
  }

  canCraft(itemName, inventory) {
    const recipe = this.recipes.get(itemName);
    if (!recipe) return false;
    for (const [ingredient, amount] of recipe.ingredients.entries()) {
      if (inventory.getItemCount(ingredient) < amount) {
        return false;
      }
    }
    return true;
  }

  craft(itemName, inventory) {
    const recipe = this.recipes.get(itemName);
    if (!recipe || !this.canCraft(itemName, inventory)) return false;
    for (const [ingredient, amount] of recipe.ingredients.entries()) {
      inventory.removeItem(ingredient, amount);
    }
    inventory.addItem(itemName, 1);
    return true;
  }
}

// Recipe System
class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = new Map(ingredients); // Map of item to amount
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, amount = 1) {
    this.items.set(item, (this.items.get(item) || 0) + amount);
  }

  removeItem(item, amount = 1) {
    if (this.items.has(item)) {
      const currentAmount = this.items.get(item);
      if (currentAmount > amount) {
        this.items.set(item, currentAmount - amount);
      } else {
        this.items.delete(item);
      }
    }
  }

  getItemCount(item) {
    return this.items.get(item) || 0;
  }

  getItems() {
    return new Map(this.items);
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    this.crafting = new Crafting();
    this.inventory = new Inventory();
  }

  initializeRecipes() {
