// Bank System
class Bank {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
            return true;
        } else {
            console.log('Deposit amount must be positive.');
            return false;
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
            return true;
        } else {
            console.log('Insufficient funds or invalid amount.');
            return false;
        }
    }

    getBalance() {
        return this.balance;
    }
}

// Market System
class Market {
    constructor() {
        this.prices = {
            apple: 10,
            banana: 5,
            carrot: 3
        };
    }

    getPrices() {
        return { ...this.prices };
    }

    buy(item, quantity, bank) {
        const price = this.prices[item];
        if (price && quantity > 0) {
            const totalCost = price * quantity;
            if (bank.withdraw(totalCost)) {
                console.log(`Bought ${quantity} ${item}(s). Total cost: ${totalCost}`);
                return true;
            } else {
                console.log('Transaction failed due to insufficient funds.');
                return false;
            }
        } else {
            console.log('Invalid item or quantity.');
            return false;
        }
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            console.log(`Added ${quantity} ${item}(s).`);
            return true;
        } else {
            console.log('Quantity must be positive.');
            return false;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && quantity > 0 && quantity <= this.items[item]) {
            this.items[item] -= quantity;
            console.log(`Removed ${quantity} ${item}(s).`);
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        } else {
            console.log('Invalid item or quantity.');
            return false;
        }
    }

    getInventory() {
        return { ...this.items };
    }
}

// Coordinator System
class Coordinator {
    constructor() {
        this.bank = new Bank();
        this.market = new Market();
        this.inventory = new Inventory();
    }

    executeTransaction(item, quantity) {
        const prices = this.market.getPrices();
        const price = prices[item];

        if (price && quantity > 0) {
            const totalCost = price * quantity;
            if (this.bank.withdraw(totalCost)) {
                this.inventory.addItem(item, quantity);
                console.log(`Transaction successful: Bought ${quantity} ${item}(s) for ${totalCost}.`);
            } else {
                console.log(`Transaction failed: Insufficient funds for ${quantity} ${item}(s).`);
            }
        } else {
            console.log(`Invalid item or quantity: ${item}, ${quantity}`);
        }
    }

