// Bank system
class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

// Market system
class Market {
  constructor(prices = {}) {
    this.prices = prices; // { item: price }
  }

  buy(item, quantity, bank) {
    const price = this.prices[item];
    if (price !== undefined && quantity > 0) {
      const totalCost = price * quantity;
      if (bank.withdraw(totalCost)) {
        return { item, quantity, cost: totalCost };
      }
    }
    return null; // Not enough money or item not available
  }

  sell(item, quantity, bank) {
    const price = this.prices[item];
    if (price !== undefined && quantity > 0) {
      const totalEarnings = price * quantity;
      bank.deposit(totalEarnings);
      return { item, quantity, earnings: totalEarnings };
    }
    return null; // Item not available
  }

  getItemPrice(item) {
    return this.prices[item] || null;
  }
}

// Inventory system
class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

