class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItem(item, quantity = 1) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (!inventory.hasItem(ingredient, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return null;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (!inventory.removeItem(ingredient, quantity)) {
        return null;
      }
    }

    // For simplicity, let's assume crafting produces the recipe name as an item
    inventory.addItem(recipe.getName());
    return recipe.getName();
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.craftingSystem = new Crafting();
    this.inventorySystem = new Inventory();
  }

  addRecipe(name, ingredients) {
    const recipe = new Recipe(name, ingredients);
    this.craftingSystem.addRecipe(recipe);
  }

  addItemToInventory(item, quantity) {
    this.inventorySystem.addItem(item, quantity);
  }

  canCraft(recipeName) {
    return this.craftingSystem.canCraft(recipeName, this.inventorySystem);
  }

  craft(recipeName) {
    return this.craftingSystem.craft(recipeName, this.inventorySystem);
  }

  getInventory() {
    return this.inventorySystem.getItems();
  }
}

