        return this._items.slice(); // Return a copy to prevent external modification
    }

    purchase(itemName, wallet) {
        const item = this._items.find(i => i.name === itemName);
        if (item && wallet.withdraw(item.price)) {
            return item;
        }
        return null;
    }
}

