class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor() {
        this.prices = {};
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getQuantity(item) {
        return this.items[item] || 0;
    }
}

class GameCoordinator {
    constructor() {
        this.bank = new Bank();
        this.market = new Market();
        this.inventory = new Inventory();
    }

    buyItem(item, quantity) {
        const price = this.market.getPrice(item);
        const totalCost = price * quantity;

        if (price !== null && this.bank.withdraw(totalCost)) {
            this.inventory.addItem(item, quantity);
            return true;
        }
        return false;
    }

    sellItem(item, quantity) {
        const price = this.market.getPrice(item);
        const totalEarnings = price * quantity;

        if (price !== null && this.inventory.removeItem(item, quantity)) {
            this.bank.deposit(totalEarnings);
            return true;
        }
        return false;
    }

    getBankBalance() {
        return this.bank.getBalance();
    }

    getInventoryQuantity(item) {
        return this.inventory.getQuantity(item);
    }
}

