class RarityTable {
  constructor(rarityData) {
    this.rarityData = rarityData;
  }

  rollRarity() {
    const totalWeight = this.rarityData.reduce((acc, item) => acc + item.weight, 0);
    const roll = Math.random() * totalWeight;

    let cumulativeWeight = 0;
    for (const item of this.rarityData) {
      cumulativeWeight += item.weight;
      if (roll < cumulativeWeight) {
