class TradeSystem {
  constructor() {
    this.trades = {};
  }

  recordTrade(item, quantity, faction) {
    if (!this.trades[faction]) {
      this.trades[faction] = {};
    }
    if (!this.trades[faction][item]) {
      this.trades[faction][item] = 0;
    }
    this.trades[faction][item] += quantity;
  }

  getTradeHistory(faction) {
    return this.trades[faction] || {};
  }
}

class ReputationSystem {
  constructor() {
    this.reputations = {};
  }

  updateReputation(faction, change) {
    if (!this.reputations[faction]) {
      this.reputations[faction] = 0;
    }
    this.reputations[faction] += change;
  }

  getReputation(faction) {
    return this.reputations[faction] || 0;
  }
}

class FactionSystem {
  constructor(tradeSystem, reputationSystem) {
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
  }

  tradeWithFaction(faction, item, quantity) {
    this.tradeSystem.recordTrade(item, quantity, faction);
    const change = quantity > 0 ? 1 : -1;
    this.reputationSystem.updateReputation(faction, change);
  }

  getFactionStatus(faction) {
    return {
      tradeHistory: this.tradeSystem.getTradeHistory(faction),
      reputation: this.reputationSystem.getReputation(faction)
    };
  }
}

