  }
}

class Faction {
  constructor(trade, reputation) {
    this.trade = trade;
    this.reputation = reputation;
  }

  tradeResource(otherFaction, resource, amount) {
    if (this.trade.getResourceAmount(resource) >= amount) {
      this.trade.removeResource(resource, amount);
      otherFaction.trade.addResource(resource, amount);
      this.reputation.changeStanding(otherFaction.name, 1);
      return true;
    }
    return false;
  }

  receiveTrade(otherFaction, resource, amount) {
    this.trade.addResource(resource, amount);
    this.reputation.changeStanding(otherFaction.name, 1);
  }

  getTradeResourceAmount(resource) {
    return this.trade.getResourceAmount(resource);
  }

  getReputationStanding(faction) {
    return this.reputation.getStanding(faction);
  }
}

