class EventBus {
    constructor() {
        this.listeners = {};
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }
}

class Pricing {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('store:productSold', this.onProductSold.bind(this));
    }

    onProductSold(product) {
        console.log(`Pricing: Product ${product.name} sold for ${product.price}`);
        // Adjust price based on demand or other factors
        product.price *= 0.95; // Example: reduce price by 5%
        this.eventBus.emit('pricing:priceAdjusted', product);
    }

    adjustPrice(product) {
        this.eventBus.emit('store:sellProduct', product);
    }
}

class Demand {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('store:productSold', this.onProductSold.bind(this));
        this.demandMap = {};
    }

    onProductSold(product) {
        console.log(`Demand: Product ${product.name} sold`);
        this.demandMap[product.name] = (this.demandMap[product.name] || 0) + 1;
        if (this.demandMap[product.name] > 10) {
            console.log(`Demand: High demand for ${product.name}`);
            this.eventBus.emit('demand:highDemand', product);
        }
    }

    checkDemand(product) {
        return this.demandMap[product.name] || 0;
    }
}

class Store {
