        this.eventBus = eventBus;
        this.eventBus.subscribe('pricing:priceAdjusted', this.onPriceAdjusted.bind(this));
        this.eventBus.subscribe('demand:highDemand', this.onHighDemand.bind(this));
        this.inventory = [];
    }

