class EventBus {
    constructor() {
        this.events = {};
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => callback(data));
        }
    }

    subscribe(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
    }
}

class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('harvest', this.harvest.bind(this));
        this.eventBus.subscribe('sellCrop', this.sellCrop.bind(this));
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
        console.log(`Planted ${crop.type} crop.`);
    }

    harvest() {
        const harvestedCrops = this.crops.map(crop => {
            crop.harvested = true;
            return crop;
        });
        console.log(`Harvested crops: ${harvestedCrops.map(crop => crop.type).join(', ')}`);
        this.eventBus.emit('cropsHarvested', harvestedCrops);
    }

    sellCrop(crop) {
        if (crop.harvested) {
            console.log(`Sold ${crop.type} crop.`);
            this.crops = this.crops.filter(cropInFarm => cropInFarm !== crop);
            this.eventBus.emit('cropSold', crop);
        } else {
            console.log(`${crop.type} crop is not harvested yet.`);
        }
    }
}

class Crop {
    constructor(type) {
        this.type = type;
        this.harvested = false;
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('cropsHarvested', this.buyCrops.bind(this));
        this.eventBus.subscribe('cropSold', this.updateInventory.bind(this));
        this.inventory = {};
    }

    buyCrops(crops) {
        crops.forEach(crop => {
            if (this.inventory[crop.type]) {
                this.inventory[crop.type]++;
            } else {
                this.inventory[crop.type] = 1;
            }
        });
        console.log(`Market bought ${crops.length} crops. Current inventory:`, this.inventory);
    }

    updateInventory(crop) {
        if (this.inventory[crop.type]) {
            this.inventory[crop.type]--;
            if (this.inventory[crop.type] === 0) {
                delete this.inventory[crop.type];
            }
        }
        console.log(`Updated inventory after selling ${crop.type} crop. Current inventory:`, this.inventory);
    }
}

// Runnable demo
const eventBus = new EventBus();
const farm = new Farm(eventBus);
const market = new Market(eventBus);

