const wheatCrop = new Crop('wheat');

farm.plantCrop(cornCrop);
farm.plantCrop(wheatCrop);

setTimeout(() => {
    farm.harvest();
}, 1000);

setTimeout(() => {
    farm.sellCrop(cornCrop);
}, 2000);

setTimeout(() => {
    farm.sellCrop(wheatCrop);
}, 3000);
