class Quest {
    constructor() {
        this.activeQuests = [];
    }

    startQuest(questId, description) {
        this.activeQuests.push({ id: questId, description, completed: false });
        console.log(`Quest started: ${description}`);
    }

    completeQuest(questId) {
        const quest = this.activeQuests.find(q => q.id === questId);
        if (quest) {
            quest.completed = true;
            console.log(`Quest completed: ${quest.description}`);
            return quest;
        }
        console.log(`Quest not found: ${questId}`);
        return null;
    }

    getActiveQuests() {
        return this.activeQuests.filter(q => !q.completed);
    }
}

class Reward {
    constructor() {
        this.rewards = [];
    }

    addReward(rewardId, description, points) {
        this.rewards.push({ id: rewardId, description, points });
        console.log(`Reward added: ${description}`);
    }

    grantReward(player, rewardId) {
        const reward = this.rewards.find(r => r.id === rewardId);
        if (reward) {
            console.log(`${player} received reward: ${reward.description}`);
            return reward;
        }
        console.log(`Reward not found: ${rewardId}`);
        return null;
    }
}

class Inventory {
