        this.items = [];
    }

    addItem(itemName, quantity) {
        this.items.push({ name: itemName, quantity });
        console.log(`Item added to inventory: ${itemName}`);
    }

    useItem(itemName, quantity = 1) {
        const item = this.items.find(i => i.name === itemName);
        if (item && item.quantity >= quantity) {
            item.quantity -= quantity;
            console.log(`Used ${quantity} of ${itemName}`);
            if (item.quantity === 0) {
                this.items = this.items.filter(i => i !== item);
            }
            return true;
        }
        console.log(`Not enough ${itemName} in inventory`);
        return false;
    }

    getInventory() {
        return this.items;
    }
}

