        }
    }

    useItem(player, itemName, quantity) {
        if (this.inventorySystem.useItem(itemName, quantity)) {
            console.log(`${player} used ${quantity} of ${itemName}`);
        }
    }

    showStatus() {
        console.log("Active Quests:", this.questSystem.getActiveQuests());
        console.log("Inventory:", this.inventorySystem.getInventory());
    }
}

