class Hunger {
  constructor(maxHunger = 100) {
    this.currentHunger = 0;
    this.maxHunger = maxHunger;
  }

  eat(amount) {
    this.currentHunger = Math.max(0, this.currentHunger - amount);
  }

  update(elapsedTime) {
    this.currentHunger = Math.min(this.maxHunger, this.currentHunger + elapsedTime);
  }

  getHungerLevel() {
    return this.currentHunger;
  }
}

class Energy {
  constructor(maxEnergy = 100) {
    this.currentEnergy = maxEnergy;
    this.maxEnergy = maxEnergy;
  }

  rest(amount) {
    this.currentEnergy = Math.min(this.maxEnergy, this.currentEnergy + amount);
  }

  expend(amount) {
    this.currentEnergy = Math.max(0, this.currentEnergy - amount);
  }

  update(elapsedTime) {
    this.currentEnergy = Math.max(0, this.currentEnergy - elapsedTime);
  }

  getEnergyLevel() {
    return this.currentEnergy;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick(seconds) {
    this.time += seconds;
  }

  getTime() {
    return this.time;
  }
}

class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  update(seconds) {
    this.clock.tick(seconds);
    this.hunger.update(seconds);
    this.energy.update(seconds);
  }

  eat(amount) {
    this.hunger.eat(amount);
  }

  rest(amount) {
    this.energy.rest(amount);
  }

  expend(amount) {
    this.energy.expend(amount);
  }

  reportStatus() {
