// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Bank System
class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Insufficient funds or invalid amount');
    }
  }
}

// Market System
class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { apple: 1, banana: 2, orange: 3 };
    this.eventBus.subscribe('sell', this.sell.bind(this));
  }

  sell(item, quantity) {
    if (this.prices[item] && quantity > 0) {
      const totalCost = this.prices[item] * quantity;
      console.log(`Selling ${quantity} ${item}(s) for ${totalCost}`);
      this.eventBus.emit('sellRequested', { item, quantity, totalCost });
    } else {
      console.log('Invalid item or quantity');
    }
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { apple: 0, banana: 0, orange: 0 };
    this.eventBus.subscribe('sellRequested', this.processSell.bind(this));
    this.eventBus.subscribe('itemBought', this.addItem.bind(this));
  }

  processSell(data) {
    const { item, quantity } = data;
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Sold ${quantity} ${item}(s), remaining: ${this.items[item]}`);
      this.eventBus.emit('sellConfirmed', data);
    } else {
      console.log(`Insufficient inventory for ${item}`);
    }
  }

  addItem(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s), new total: ${this.items[item]}`);
    } else {
      console.log('Invalid item or quantity');
    }
  }
}

// Demo
