        this.listeners = {};
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }
}

// Define the Recipe System
class Recipe {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.recipes = {};
        this.eventBus.subscribe('craft', this.handleCraftRequest.bind(this));
    }

    addRecipe(item, ingredients) {
        this.recipes[item] = ingredients;
    }

    handleCraftRequest(item) {
        const ingredients = this.recipes[item];
        if (ingredients) {
            this.eventBus.emit('checkIngredients', { item, ingredients });
        } else {
            console.log(`No recipe found for ${item}`);
        }
    }
}

// Define the Inventory System
class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};
        this.eventBus.subscribe('checkIngredients', this.checkIngredients.bind(this));
        this.eventBus.subscribe('removeIngredients', this.removeIngredients.bind(this));
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    checkIngredients({ item, ingredients }) {
        let canCraft = true;
        for (const ingredient in ingredients) {
            if (this.items[ingredient] && this.items[ingredient] >= ingredients[ingredient]) {
                continue;
            }
            canCraft = false;
            break;
        }
        if (canCraft) {
            this.eventBus.emit('removeIngredients', { item, ingredients });
            this.addItem(item);
            console.log(`Crafted ${item}`);
        } else {
            console.log(`Not enough ingredients to craft ${item}`);
        }
    }

    removeIngredients({ item, ingredients }) {
        for (const ingredient in ingredients) {
            this.items[ingredient] -= ingredients[ingredient];
        }
    }
}

// Define the Crafting System
class Crafting {
    constructor(eventBus) {
        this.eventBus = eventBus;
    }

    craft(item) {
        this.eventBus.emit('craft', item);
    }
}

