    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('sellAttempt', this.handleSellAttempt.bind(this));
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
    console.log(`Added ${item} to inventory.`);
  }

  removeItem(item) {
    if (this.items[item] > 0) {
      this.items[item]--;
      console.log(`Removed ${item} from inventory.`);
      return true;
    } else {
      console.log(`Item not found in inventory: ${item}`);
      return false;
    }
  }

  handlePurchaseSuccess({ item }) {
    if (this.removeItem(item)) {
      this.eventBus.emit('sellAttempt', { itemPrice: this.getPrice(item), item });
    }
  }

  handleSellAttempt({ itemPrice, item }) {
    this.addItem(item);
  }

  getPrice(item) {
    return {
      sword: 40,
      shield: 25,
      potion: 8
    }[item] || 0;
  }
}

