class Quest {
  constructor() {
    this.quests = {};
  }

  addQuest(key, description, requirements) {
    this.quests[key] = { description, requirements };
  }

  isQuestComplete(key, flags) {
    const quest = this.quests[key];
    if (!quest) return false;
    return quest.requirements.every(flag => flags.getFlag(flag));
  }

  getQuestDescription(key) {
    const quest = this.quests[key];
    return quest ? quest.description : "Quest not found.";
  }
}

