const store = new Store(pricing, demand);

store.sell(10); // Sold 10 items for 100 gold.
store.updatePrice(15);
store.sell(10); // Sold 10 items for 150 gold.
store.restock(20); // Restocked 20 items.
store.sell(30); // Cannot sell 30 items, demand is only 30.
