        this.rarityTable = rarityTable;
        this.inventory = inventory;
        this.prices = {
            COMMON: 10,
            UNCOMMON: 50,
            RARE: 100,
            LEGENDARY: 500
        };
    }

    purchaseItem() {
        const rarity = this.rarityTable.getRandomRarity();
        const price = this.prices[rarity];
        try {
            this.economy.debit(price);
            const item = { rarity, price };
            this.inventory.addItem(item);
            console.log(`Purchased ${rarity} item for ${price}. Remaining balance: ${this.economy.getBalance()}`);
        } catch (error) {
            console.error(error.message);
        }
    }
