    this.factions = {
      traders: 0,
      merchants: 0,
      pirates: 0
    };
  }

  // Public API
  joinFaction(faction) {
    if (this.factions[faction] === undefined) {
      console.log(`Unknown faction: ${faction}`);
      return false;
    }
    this.factions[faction]++;
    console.log(`Joined ${faction}. Total members: ${this.factions[faction]}`);
    return true;
  }

  leaveFaction(faction) {
    if (this.factions[faction] === undefined || this.factions[faction] <= 0) {
      console.log(`Cannot leave faction: ${faction}`);
      return false;
    }
    this.factions[faction]--;
    console.log(`Left ${faction}. Remaining members: ${this.factions[faction]}`);
    return true;
  }
}

