class Quest {
  constructor() {
    this.quests = [];
  }

  addQuest(title, description) {
    this.quests.push({ title, description, completed: false });
    console.log(`Quest added: ${title}`);
  }

  completeQuest(title) {
    const quest = this.quests.find(q => q.title === title);
    if (quest) {
      quest.completed = true;
      console.log(`Quest completed: ${title}`);
    } else {
      console.log(`Quest not found: ${title}`);
    }
  }

  getActiveQuests() {
    return this.quests.filter(q => !q.completed);
  }
}

class Reward {
  constructor() {
    this.rewards = [];
  }

  addReward(name, description) {
    this.rewards.push({ name, description });
    console.log(`Reward added: ${name}`);
  }

  grantReward(name) {
    const reward = this.rewards.find(r => r.name === name);
    if (reward) {
      console.log(`Reward granted: ${name}`);
    } else {
      console.log(`Reward not found: ${name}`);
    }
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(name, quantity) {
    this.items.push({ name, quantity });
    console.log(`Item added to inventory: ${name} (x${quantity})`);
  }

  removeItem(name, quantity) {
    const item = this.items.find(i => i.name === name);
    if (item && item.quantity >= quantity) {
      item.quantity -= quantity;
      console.log(`Item removed from inventory: ${name} (x${quantity})`);
      if (item.quantity === 0) {
        this.items = this.items.filter(i => i.name !== name);
      }
    } else {
      console.log(`Insufficient quantity or item not found: ${name}`);
    }
  }

  getInventory() {
    return this.items;
  }
}

class GameCoordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startGame() {
    console.log("Game started!");
  }

  completeQuest(title) {
    this.questSystem.completeQuest(title);
    const quests = this.questSystem.getActiveQuests();
    if (quests.length === 0) {
      this.grantRewards();
    }
  }

  grantRewards() {
    this.rewardSystem.addReward("Gold", "A pile of gold");
    this.rewardSystem.grantReward("Gold");
    this.inventorySystem.addItem("Potion", 3);
  }
}

