class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  hasItem(item, amount = 1) {
    return (this.items[item] || 0) >= amount;
  }

  addItem(item, amount = 1) {
    this.items[item] = (this.items[item] || 0) + amount;
  }

  removeItem(item, amount = 1) {
    if (this.hasItem(item, amount)) {
      this.items[item] -= amount;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  canCraft(inventory) {
    return this.ingredients.every(([item, amount]) => inventory.hasItem(item, amount));
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(recipe => recipe.name === recipeName);
    if (recipe && recipe.canCraft(this.inventory)) {
      recipe.ingredients.forEach(([item, amount]) => this.inventory.removeItem(item, amount));
      this.inventory.addItem(recipe.result);
      return true;
    }
    return false;
  }

  getCraftableRecipes() {
    return this.recipes.filter(recipe => recipe.canCraft(this.inventory)).map(recipe => recipe.name);
  }
}

