class Combat {
    constructor() {
        this.onDamageTaken = null;
        this.onAttack = null;
    }

    takeDamage(amount) {
        if (this.onDamageTaken) {
            this.onDamageTaken(amount);
        }
    }

    attack(target, damage) {
        if (this.onAttack) {
            this.onAttack(target, damage);
        }
    }
}

class Health {
    constructor(maxHealth) {
        this.currentHealth = maxHealth;
        this.onHealthChange = null;
    }

    takeDamage(amount) {
        this.currentHealth -= amount;
        if (this.currentHealth < 0) {
            this.currentHealth = 0;
        }
        if (this.onHealthChange) {
            this.onHealthChange(this.currentHealth);
        }
    }

    heal(amount) {
        this.currentHealth += amount;
        if (this.currentHealth > this.maxHealth) {
            this.currentHealth = this.maxHealth;
        }
        if (this.onHealthChange) {
            this.onHealthChange(this.currentHealth);
        }
    }
}

class Loot {
    constructor() {
        this.onLootGenerated = null;
    }

    generateLoot(amount) {
        if (this.onLootGenerated) {
            this.onLootGenerated(amount);
        }
    }
}

class GameCoordinator {
    constructor() {
        this.combat = new Combat();
        this.health = new Health(100);
        this.loot = new Loot();

        // Wire up Combat to Health
        this.combat.onDamageTaken = (amount) => {
            this.health.takeDamage(amount);
        };

        // Wire up Combat to Loot
        this.combat.onAttack = (target, damage) => {
            console.log(`${target} attacked for ${damage} damage.`);
            // Simple loot drop logic
            if (Math.random() < 0.2) {
                const lootAmount = Math.floor(Math.random() * 10) + 1;
                this.loot.generateLoot(lootAmount);
            }
        };

        // Wire up Health to Loot
        this.health.onHealthChange = (currentHealth) => {
            console.log(`Health is now ${currentHealth}.`);
            if (currentHealth === 0) {
                console.log("Game Over!");
            }
        };

        // Wire up Loot to console
        this.loot.onLootGenerated = (amount) => {
            console.log(`Loot generated: ${amount} gold.`);
        };
    }

    startCombat() {
        this.combat.attack("Enemy", 20);
        this.combat.attack("Enemy", 30);
        this.health.heal(10);
        this.combat.attack("Enemy", 50);
    }
}

