class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  hasIngredients(recipe) {
    for (const [ingredient, requiredQty] of Object.entries(recipe.ingredients)) {
      if (!this.items[ingredient] || this.items[ingredient] < requiredQty) {
        return false;
      }
    }
    return true;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe instances
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    return this.inventory.hasIngredients(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    if (!this.inventory.hasIngredients(recipe)) return false;

    for (const [ingredient, requiredQty] of Object.entries(recipe.ingredients)) {
      this.inventory.removeItem(ingredient, requiredQty);
    }

    console.log(`Crafted ${recipeName}`);
    return true;
  }
}

