class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
    } else {
      console.log("Deposit amount must be positive");
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
      return true;
    } else {
      console.log("Insufficient funds or invalid amount");
      return false;
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  getAllPrices() {
    return { ...this.prices };
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      console.log(`Added ${quantity} of ${item}, total: ${this.items[item]}`);
    } else {
      console.log("Quantity must be positive");
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

