class Economy {
  constructor() {
    this.bank = new Bank();
    this.market = new Market({ apple: 1, banana: 2, orange: 3 });
    this.inventory = new Inventory();
  }

  purchase(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      if (this.bank.withdraw(totalCost)) {
        this.inventory.addItem(item, quantity);
        console.log(`Purchased ${quantity} of ${item} for ${totalCost}`);
      } else {
        console.log("Purchase failed: insufficient funds");
      }
    } else {
      console.log("Item not available in the market");
    }
  }

  deposit(amount) {
    this.bank.deposit(amount);
  }

  getBalance() {
    return this.bank.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }

  getMarketPrices() {
    return this.market.getAllPrices();
  }
}

