class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.levelUp.bind(this));
  }

  learn(skillName, level) {
    this.skills[skillName] = level;
    console.log(`Learned ${skillName} at level ${level}`);
    this.eventBus.emit('skillLearned', { skillName, level });
  }

  levelUp(levels) {
    for (const skill in this.skills) {
      this.skills[skill] += levels;
      console.log(`Skill ${skill} leveled up to ${this.skills[skill]}`);
    }
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('skillLearned', this.gainExperience.bind(this));
  }

  gainExperience({ level }) {
    const experienceGained = level * 10;
    this.experiencePoints += experienceGained;
    console.log(`Gained ${experienceGained} experience points`);
    this.eventBus.emit('experienceGained', { experienceGained });
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.level = 1;
    this.eventBus.subscribe('experienceGained', this.checkLevelUp.bind(this));
  }

  checkLevelUp({ experienceGained }) {
    const experienceNeeded = this.level * 100;
    if (this.experiencePoints + experienceGained >= experienceNeeded) {
      this.levelUp();
    }
  }

  levelUp() {
    this.level++;
    console.log(`Leveled up to level ${this.level}`);
    this.eventBus.emit('levelUp', this.level);
  }
}

