// Crafting System
class Crafting {
  constructor() {
    this.craftingTable = [];
  }

  addRecipe(recipe) {
    this.craftingTable.push(recipe);
  }

  craft(recipeName, inventory) {
    const recipe = this.craftingTable.find(r => r.name === recipeName);
    if (!recipe) return null;

    if (recipe.ingredients.every(ingr => inventory.hasItem(ingr.name, ingr.quantity))) {
      recipe.ingredients.forEach(ingr => inventory.removeItem(ingr.name, ingr.quantity));
      return recipe.result;
    }
    return null;
  }
}

// Recipe System
class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(name, quantity) {
    if (this.items[name]) {
      this.items[name] += quantity;
    } else {
      this.items[name] = quantity;
    }
  }

  removeItem(name, quantity) {
    if (this.items[name] && this.items[name] >= quantity) {
      this.items[name] -= quantity;
      if (this.items[name] === 0) {
        delete this.items[name];
      }
    }
  }

  hasItem(name, quantity) {
    return this.items[name] && this.items[name] >= quantity;
  }
}

