class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting();
  }

  initialize() {
    // Adding some initial items to inventory
    this.inventory.addItem('wood', 10);
    this.inventory.addItem('stone', 5);

    // Adding recipes
    const stickRecipe = new Recipe('stick', [{ name: 'wood', quantity: 2 }], 'stick');
    const axeRecipe = new Recipe('axe', [{ name: 'stick', quantity: 1 }, { name: 'stone', quantity: 1 }], 'axe');
    this.crafting.addRecipe(stickRecipe);
    this.crafting.addRecipe(axeRecipe);
