class Wallet {
  constructor(initialAmount = 0) {
    this.balance = initialAmount;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor() {
    this.items = {
      potion: { price: 10, quantity: 5 },
      sword: { price: 50, quantity: 2 },
    };
  }

  getItemPrice(itemName) {
    return this.items[itemName]?.price || 0;
  }

  buyItem(itemName, wallet) {
    const item = this.items[itemName];
    if (item && item.quantity > 0 && wallet.withdraw(item.price)) {
      item.quantity -= 1;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName) {
    if (this.items[itemName]) {
      this.items[itemName].quantity += 1;
    } else {
      this.items[itemName] = { quantity: 1 };
    }
  }

  getItemCount(itemName) {
    return this.items[itemName]?.quantity || 0;
  }
}

class GameCoordinator {
  constructor(wallet, shop, inventory) {
    this.wallet = wallet;
    this.shop = shop;
    this.inventory = inventory;
  }

  depositToWallet(amount) {
    this.wallet.deposit(amount);
  }

  buyItem(itemName) {
    const price = this.shop.getItemPrice(itemName);
    if (this.wallet.withdraw(price)) {
      this.shop.buyItem(itemName, this.wallet);
      this.inventory.addItem(itemName);
      return true;
    }
    return false;
  }

  getWalletBalance() {
    return this.wallet.getBalance();
  }

  getItemCount(itemName) {
    return this.inventory.getItemCount(itemName);
  }
}

