class RarityTable {
  constructor() {
    this.table = {
      common: { min: 1, max: 10 },
      uncommon: { min: 11, max: 20 },
      rare: { min: 21, max: 30 },
      epic: { min: 31, max: 40 },
      legendary: { min: 41, max: 50 }
    };
  }

  rollRarity() {
    const roll = Math.floor(Math.random() * 100) + 1;
    for (const [rarity, range] of Object.entries(this.table)) {
      if (roll >= range.min && roll <= range.max) {
        return rarity;
      }
    }
    return 'common'; // Default to common if no match
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
