      uncommon: 20,
      rare: 30,
      epic: 40,
      legendary: 50
    };
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getPrice(rarity) {
    return this.prices[rarity] || 10; // Default to 10 if rarity not found
  }
}

class Store {
