class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result;
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (inventory.getQuantity(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      inventory.remove(item, quantity);
    }
    inventory.add(this.result, 1);
  }
}

