    console.log(`Added ${quantity} ${item}(s). Total: ${this.items[item]}`);
  }

  remove(item, quantity) {
    if (this.getQuantity(item) >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} ${item}(s). Remaining: ${this.items[item]}`);
    } else {
