class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
    }
  }

  handlePurchase({ item, cost }) {
    if (cost <= this.balance) {
      this.withdraw(cost);
      this.eventBus.emit('purchaseSuccess', { item, cost });
    } else {
      console.log(`Purchase failed: Insufficient funds for ${item}.`);
    }
  }
}

