  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceChanged', { balance: this.balance });
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceChanged', { balance: this.balance });
    } else {
      console.log('Insufficient funds or invalid amount');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = {
      'apple': 10,
      'banana': 5,
      'orange': 8
    };
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, amount) {
    if (this.prices[item] !== undefined && amount > 0) {
      const totalPrice = this.prices[item] * amount;
      this.eventBus.emit('requestWithdraw', { amount: totalPrice, callback: (success) => {
        if (success) {
          console.log(`Bought ${amount} ${item}(s) for ${totalPrice}`);
          this.eventBus.emit('itemBought', { item, amount });
        } else {
          console.log(`Failed to buy ${amount} ${item}(s) due to insufficient funds`);
        }
      }});
    } else {
      console.log('Invalid item or amount');
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('itemBought', this.addItem.bind(this));
  }

  addItem(itemData) {
    const { item, amount } = itemData;
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
