    return this.prices[item] || null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null && this.bank.withdraw(price * quantity)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null && this.inventory.removeItem(item, quantity)) {
      this.bank.deposit(price * quantity);
      return true;
    }
    return false;
  }

  getBalance() {
    return this.bank.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }
}

