    rest(amount) {
        this.energyLevel += amount;
        this.energyLevel = Math.min(100, this.energyLevel);
    }

    consume(amount) {
        this.energyLevel -= amount;
        this.energyLevel = Math.max(0, this.energyLevel);
    }

    update() {
        if (this.energyLevel < 100) {
            this.energyLevel += 1;
        }
