    const harvested = this.crops.map(crop => ({ ...crop, harvested: true }));
    this.crops = [];
    console.log('Harvested crops');
    return harvested;
  }
}

class Crop {
  constructor(type) {
    this.type = type;
    this.harvested = false;
  }
}

class Market {
  constructor() {
    this.inventory = [];
  }

  receiveCrops(crops) {
    this.inventory.push(...crops);
    console.log(`Received ${crops.length} crops at the market`);
  }

  sellCrop(type) {
    const cropIndex = this.inventory.findIndex(crop => crop.type === type && !crop.harvested);
    if (cropIndex !== -1) {
      const crop = this.inventory.splice(cropIndex, 1)[0];
      console.log(`Sold ${crop.type}`);
      return crop;
    }
    console.log(`No ${type} available for sale`);
    return null;
  }
}

class Coordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plantAndHarvestCycle() {
    this.farm.plantCrop(new Crop('Wheat'));
    this.farm.plantCrop(new Crop('Carrot'));
    const harvestedCrops = this.farm.harvestCrops();
    this.market.receiveCrops(harvestedCrops);
  }

  sellCrop(type) {
    return this.market.sellCrop(type);
  }
}

