    this.prices[item] = price;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Demand {
  constructor() {
    this.demand = {};
  }

  setDemand(item, quantity) {
    this.demand[item] = quantity;
  }

  getDemand(item) {
    return this.demand[item] || 0;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 0;
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const available = this.demand.getDemand(item);

    if (available >= quantity) {
      const totalCost = price * quantity;
      if (this.balance >= totalCost) {
        this.balance -= totalCost;
        this.inventory[item] = (this.inventory[item] || 0) + quantity;
        this.demand.setDemand(item, available - quantity);
        console.log(`Purchased ${quantity} of ${item}. New inventory:`, this.inventory);
      } else {
        console.log(`Insufficient balance to purchase ${quantity} of ${item}.`);
      }
    } else {
      console.log(`Insufficient demand for ${item}. Only ${available} available.`);
    }
  }

  addFunds(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to balance. New balance: ${this.balance}`);
  }
}

