    grow() {
        this.daysGrown += 1;
    }

    isReadyToHarvest() {
        return this.daysGrown >= this.growthRate;
    }

    getHarvest() {
        if (this.isReadyToHarvest()) {
            return this.daysGrown;
        }
        return 0;
    }
}

class Farm {
    constructor() {
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
    }

    growCrops() {
        this.crops.forEach(crop => crop.grow());
    }

    harvestCrops() {
        const harvested = this.crops.filter(crop => crop.isReadyToHarvest());
        this.crops = this.crops.filter(crop => !crop.isReadyToHarvest());
        return harvested;
    }
}

class Market {
    constructor() {
        this.prices = {
            wheat: 2,
            barley: 3,
            corn: 1.5
        };
    }

    sellCrop(crop, quantity) {
        const price = this.prices[crop.name] || 0;
        return price * quantity;
    }
}

