        if (quantity > this.stock) {
            console.log("Not enough stock available.");
            return;
        }
        const price = this.pricingSystem.calculatePrice(quantity);
        const demand = this.demandSystem.calculateDemand(price);
        if (demand <= 0) {
            console.log("Demand too low to sell at this price.");
            return;
        }
        this.stock -= quantity;
        console.log(`Sold ${quantity} items at price ${price}. Remaining stock: ${this.stock}`);
    }

    restock(amount) {
        this.stock += amount;
        console.log(`Restocked ${amount} items. Total stock: ${this.stock}`);
    }
}

