class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 0;
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (quantity > demand) {
      console.log(`Not enough demand for ${item}`);
      return;
    }

    const totalCost = price * quantity;
    if (totalCost > this.balance) {
      console.log(`Insufficient funds to purchase ${quantity} ${item}`);
      return;
    }

    this.balance -= totalCost;
    this.inventory[item] = (this.inventory[item] || 0) + quantity;
    this.demand.setDemand(item, demand - quantity);

    console.log(`Purchased ${quantity} ${item} for ${totalCost}`);
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount} into the store`);
  }

  getInventory() {
    return this.inventory;
  }

  getBalance() {
    return this.balance;
  }
}

