  }
}

class Loot {
  constructor() {
    this.lootTable = {};
  }

  registerLoot(item, chance) {
    this.lootTable[item] = chance;
  }

  rollForLoot() {
    const items = Object.keys(this.lootTable);
    let totalChance = items.reduce((sum, item) => sum + this.lootTable[item], 0);
    const roll = Math.random() * totalChance;

    let cumulativeChance = 0;
    for (const item of items) {
      cumulativeChance += this.lootTable[item];
      if (roll <= cumulativeChance) {
        return item;
      }
    }
    return null;
  }
}

