// Loot System
class Loot {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getAllItems() {
    return [...this.items];
  }
}

// RarityTable System
class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.1
    };
  }

  getRandomRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;
    for (const [rarity, probability] of Object.entries(this.rarityMap)) {
      cumulativeProbability += probability;
      if (rand < cumulativeProbability) {
        return rarity;
      }
    }
    return 'common'; // Fallback to common if something goes wrong
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.contents = {};
  }

  addItem(item) {
    if (this.contents[item]) {
      this.contents[item]++;
    } else {
      this.contents[item] = 1;
    }
  }

  getContents() {
    return { ...this.contents };
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.loot = new Loot();
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  generateLoot() {
    const rarity = this.rarityTable.getRandomRarity();
    const item = `${rarity} item`;
    this.loot.addItem(item);
    console.log(`Generated loot: ${item}`);
  }

  collectLoot() {
    const items = this.loot.getAllItems();
    items.forEach(item => this.inventory.addItem(item));
    this.loot.items = []; // Clear the loot after collecting
    console.log('Loot collected into inventory.');
  }

  displayInventory() {
    const contents = this.inventory.getContents();
    console.log('Inventory contents:');
    for (const [item, count] of Object.entries(contents)) {
      console.log(`${item}: ${count}`);
    }
  }
}

// Runnable demo
