class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map();
    recipes.forEach(recipe => this.recipes.set(recipe.name, recipe));
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;
    for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
      if (inventory.get(ingredient) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;
    for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
      inventory.set(ingredient, inventory.get(ingredient) - quantity);
    }
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  add(item, quantity) {
    this.items.set(item, (this.items.get(item) || 0) + quantity);
  }

  get(item) {
    return this.items.get(item) || 0;
  }

  set(item, quantity) {
    this.items.set(item, quantity);
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { itemName: price }
  }

  getCost(item) {
    return this.prices[item] || 0;
  }

  debit(item, quantity, inventory) {
    const cost = this.getCost(item) * quantity;
    if (inventory.get('gold') < cost) {
      return false;
    }
    inventory.set('gold', inventory.get('gold') - cost);
    return true;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, quantity) {
    if (this.economy.debit(item, quantity, this.inventory)) {
      this.inventory.add(item, quantity);
      return true;
    }
    return false;
  }
}

