class Resource {
  constructor(name, quantity = 0) {
    this.name = name;
    this.quantity = quantity;
  }

  getQuantity() {
    return this.quantity;
  }

  getName() {
    return this.name;
  }

  consume(amount) {
    if (amount <= this.quantity) {
      this.quantity -= amount;
      return true;
    }
    return false;
  }

  produce(amount) {
    this.quantity += amount;
  }
}

class Economy {
  constructor(buildings = [], resources = []) {
    this.buildings = buildings;
    this.resources = resources;
  }

  canBuild(buildingName) {
    const building = this.buildings.find(b => b.getName() === buildingName);
    if (!building) return false;

    const costs = building.getCosts();
    for (const [resourceName, amount] of Object.entries(costs)) {
      const resource = this.resources.find(r => r.getName() === resourceName);
      if (!resource || resource.getQuantity() < amount) {
        return false;
      }
    }
    return true;
  }

  build(buildingName) {
    if (!this.canBuild(buildingName)) return false;

    const building = this.buildings.find(b => b.getName() === buildingName);
    const costs = building.getCosts();
    for (const [resourceName, amount] of Object.entries(costs)) {
      const resource = this.resources.find(r => r.getName() === resourceName);
      resource.consume(amount);
    }
    return true;
  }

  produceResources() {
    // For demonstration, let's assume each building produces a resource equal to its cost
    this.buildings.forEach(building => {
      const costs = building.getCosts();
      for (const [resourceName, amount] of Object.entries(costs)) {
        const resource = this.resources.find(r => r.getName() === resourceName);
        resource.produce(amount);
      }
    });
  }
}

