class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory.items[item] || inventory.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    if (this.canCraft(inventory)) {
      for (const [item, quantity] of Object.entries(this.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      return true;
    }
    return false;
  }
}

class Crafting {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.name] = recipe;
  }

  craftRecipe(inventory, recipeName) {
    const recipe = this.recipes[recipeName];
    if (recipe) {
      return recipe.craft(inventory);
    }
    return false;
  }

  canCraft(inventory, recipeName) {
    const recipe = this.recipes[recipeName];
    if (recipe) {
      return recipe.canCraft(inventory);
    }
    return false;
  }
}

