class EventBus {
    constructor() {
        this.events = {};
    }

    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(handler => handler(data));
        }
    }

    subscribe(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
    }
}

class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}, new balance is ${this.balance}`);
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds: ${amount} > ${this.balance}`);
        } else {
            this.balance -= amount;
            console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
            this.eventBus.emit('funds-withdrawn', amount);
        }
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = { apple: 1, banana: 2, orange: 3 };
        this.eventBus.subscribe('buy', this.buy.bind(this));
    }

    buy(item, quantity) {
        const price = this.prices[item] || 0;
        const totalCost = price * quantity;
        this.eventBus.emit('withdraw', totalCost);
        this.eventBus.subscribe('funds-withdrawn', () => {
            console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
        });
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = { apple: 0, banana: 0, orange: 0 };
        this.eventBus.subscribe('sell', this.sell.bind(this));
    }

    sell(item, quantity) {
        if (this.items[item] >= quantity) {
            this.items[item] -= quantity;
            const price = this.items[item] * this.prices[item];
            console.log(`Sold ${quantity} ${item}(s) for ${price}`);
            this.eventBus.emit('deposit', price);
        } else {
            console.log(`Insufficient inventory: ${quantity} > ${this.items[item]}`);
        }
    }
}

// Demo
