class Trade {
  constructor(commodities) {
    this.commodities = commodities;
  }

  buy(commodity, quantity) {
    if (this.commodities[commodity] >= quantity) {
      this.commodities[commodity] -= quantity;
      return true;
    }
    return false;
  }

  sell(commodity, quantity) {
    this.commodities[commodity] += quantity;
  }

  getStock(commodity) {
    return this.commodities[commodity] || 0;
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  improve(amount) {
    this.standing += amount;
  }

  degrade(amount) {
    this.standing -= amount;
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor(tradeSystem, reputationSystem) {
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
  }

  trade(commodity, quantity) {
    if (this.tradeSystem.buy(commodity, quantity)) {
      this.reputationSystem.improve(1);
      return true;
    }
    this.reputationSystem.degrade(1);
    return false;
  }

  receiveTrade(commodity, quantity) {
    this.tradeSystem.sell(commodity, quantity);
    this.reputationSystem.improve(1);
  }

  getReputation() {
    return this.reputationSystem.getStanding();
  }

  getStock(commodity) {
    return this.tradeSystem.getStock(commodity);
  }
}

