class Quest {
    constructor(flagsSystem) {
        this.flagsSystem = flagsSystem;
        this.quests = {
            "rescuePrincess": {
                status: "inactive",
                requirements: {
                    "talkToKing": false
                }
            }
        };
    }

    checkForDialogueTrigger(character, message) {
        if (character === "King" && message === "Have you rescued the princess?") {
            this.flagsSystem.setFlag("talkToKing", true);
            this.updateQuestStatus("rescuePrincess");
        }
    }

    updateQuestStatus(questName) {
        const quest = this.quests[questName];
        if (quest && quest.status === "inactive") {
            let allRequirementsMet = true;
            for (const requirement in quest.requirements) {
                if (!this.flagsSystem.getFlag(requirement)) {
                    allRequirementsMet = false;
                    break;
                }
            }
            if (allRequirementsMet) {
                quest.status = "completed";
                console.log(`Quest "${questName}" completed!`);
            }
        }
    }
}

