class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(demandLevel) {
    // Simple pricing model: price increases with demand
    return this.basePrice * (1 + demandLevel * 0.1);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  updateDemand(change) {
    this.demand += change;
    if (this.demand < 0) this.demand = 0; // Demand cannot be negative
  }

  getDemandLevel() {
    return this.demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellItem() {
    const demandLevel = this.demand.getDemandLevel();
    const price = this.pricing.calculatePrice(demandLevel);
    console.log(`Sold item at price: $${price.toFixed(2)}`);
    this.demand.updateDemand(-1); // Reduce demand after sale
  }

  restock() {
    console.log("Restocking store...");
    this.demand.updateDemand(5); // Increase demand on restock
  }
}

