// Building System
class Building {
    constructor() {
        this.buildings = {};
    }

    build(name, cost) {
        if (this.canAfford(cost)) {
            this.buildings[name] = (this.buildings[name] || 0) + 1;
            return true;
        }
        return false;
    }

    canAfford(cost) {
        for (const [resource, amount] of Object.entries(cost)) {
            if (!this.buildings[resource] || this.buildings[resource] < amount) {
                return false;
            }
        }
        return true;
    }

    getBuildingCount(name) {
        return this.buildings[name] || 0;
    }
}

// Resource System
class Resource {
    constructor() {
        this.resources = {};
    }

    gather(resource, amount) {
        this.resources[resource] = (this.resources[resource] || 0) + amount;
    }

    spend(resource, amount) {
        if (this.resources[resource] && this.resources[resource] >= amount) {
            this.resources[resource] -= amount;
            return true;
        }
        return false;
    }

    getResourceAmount(resource) {
        return this.resources[resource] || 0;
    }
}

// Economy System
class Economy {
    constructor(buildingSystem, resourceSystem) {
        this.buildingSystem = buildingSystem;
        this.resourceSystem = resourceSystem;
    }

    upgradeBuilding(name, cost) {
        if (this.resourceSystem.spend('gold', cost.gold) && this.resourceSystem.spend('wood', cost.wood)) {
            this.buildingSystem.build(name, cost);
            return true;
        }
        return false;
    }

    gatherResources() {
        const lumberyardCount = this.buildingSystem.getBuildingCount('lumberyard');
        const mineCount = this.buildingSystem.getBuildingCount('mine');

        this.resourceSystem.gather('wood', lumberyardCount * 10);
        this.resourceSystem.gather('gold', mineCount * 5);
    }
}

