class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Bank: Deposited ${amount}, new balance is ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Bank: Withdrew ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('itemBought', amount);
    } else {
      console.log(`Bank: Insufficient funds for withdrawal of ${amount}`);
    }
  }
}

class Market {
  constructor(eventBus) {
    this.prices = { apple: 1, banana: 2, orange: 3 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item) {
    const price = this.prices[item];
    if (price) {
      console.log(`Market: Attempting to buy ${item} for ${price}`);
      this.eventBus.emit('withdraw', price);
    } else {
      console.log(`Market: Item ${item} not available`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemBought', this.addItem.bind(this));
  }

  addItem(price) {
    const item = Object.keys(this.eventBus.market.prices).find(
      item => this.eventBus.market.prices[item] === price
    );
    if (item) {
      this.items[item] = (this.items[item] || 0) + 1;
      console.log(`Inventory: Added ${item}, new inventory is ${JSON.stringify(this.items)}`);
    }
  }
}

