class Loot {
    constructor(itemName, rarity) {
        this.itemName = itemName;
        this.rarity = rarity;
    }
}

class RarityTable {
    constructor() {
        this.rarityLevels = {
            common: { probability: 0.7, price: 10 },
            uncommon: { probability: 0.2, price: 20 },
            rare: { probability: 0.08, price: 50 },
            epic: { probability: 0.02, price: 100 }
        };
    }

    rollLoot() {
        const random = Math.random();
        let cumulativeProbability = 0;

        for (const [rarity, data] of Object.entries(this.rarityLevels)) {
            cumulativeProbability += data.probability;
            if (random <= cumulativeProbability) {
                return new Loot(`Item-${rarity}`, rarity);
            }
        }

        return new Loot('Unknown', 'common');
    }
}

class Inventory {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
    }

    listItems() {
        return this.items.map(item => `${item.itemName} (${item.rarity})`);
    }
}

class Economy {
    constructor(initialBalance = 100) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error('Insufficient funds');
        }
        this.balance -= amount;
    }
}

class Store {
    constructor(economy, rarityTable, inventory) {
        this.economy = economy;
        this.rarityTable = rarityTable;
        this.inventory = inventory;
    }

    purchaseItem() {
        const loot = this.rarityTable.rollLoot();
        const price = this.rarityTable.rarityLevels[loot.rarity].price;

        if (this.economy.getBalance() >= price) {
            this.economy.debit(price);
            this.inventory.addItem(loot);
            console.log(`Purchased ${loot.itemName} (${loot.rarity}) for ${price}.`);
        } else {
            console.log('Insufficient funds to purchase item.');
        }
    }
}

