      'sword': { price: 50, stock: 10 },
      'potion': { price: 10, stock: 20 }
    };
  }

  getItemPrice(item) {
    return this.items[item]?.price || 0;
  }

  getItemStock(item) {
    return this.items[item]?.stock || 0;
  }

  purchaseItem(item, economy) {
    const price = this.getItemPrice(item);
    const stock = this.getItemStock(item);

    if (stock <= 0) {
      console.log(`Item ${item} is out of stock.`);
      return false;
    }

    if (economy.withdraw(price)) {
      this.items[item].stock -= 1;
      console.log(`Purchased ${item} for ${price}. Remaining stock: ${this.items[item].stock}`);
      return true;
    }

    return false;
  }
