class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor() {
    this.items = new Map([
      ['potion', { price: 10, description: 'Heals 20 HP' }],
      ['sword', { price: 50, description: 'Deals 50 damage' }],
    ]);
  }

  getItemPrice(item) {
    const itemInfo = this.items.get(item);
    return itemInfo ? itemInfo.price : null;
  }

  getItemDescription(item) {
    const itemInfo = this.items.get(item);
    return itemInfo ? itemInfo.description : null;
  }

  listItems() {
    return Array.from(this.items.keys());
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items.set(item, (this.items.get(item) || 0) + quantity);
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items.has(item) && this.items.get(item) >= quantity) {
      const newQuantity = this.items.get(item) - quantity;
      if (newQuantity === 0) {
        this.items.delete(item);
      } else {
        this.items.set(item, newQuantity);
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return Object.fromEntries(this.items);
  }
}

