    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Added ${quantity} ${item}(s).`);
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} ${item}(s).`);
    } else {
      console.log(`Not enough ${item}(s) to remove.`);
    }
  }

  craft(recipe) {
    if (this.checkIngredients(recipe)) {
      this.removeItem(recipe.inputItem, recipe.inputQuantity);
      this.addItem(recipe.outputItem, recipe.outputQuantity);
      console.log(`Crafted ${recipe.outputQuantity} ${recipe.outputItem}(s).`);
    } else {
      console.log(`Missing ingredients for crafting ${recipe.outputItem}.`);
