class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('sell', this.handleSell.bind(this));
    this.eventBus.subscribe('buy', this.handleBuy.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}, New Balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, New Balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Current Balance: ${this.balance}`);
      return false;
    }
  }

  handleSell(data) {
    if (this.withdraw(data.amount)) {
      this.eventBus.emit('sellSuccess', data);
    } else {
      this.eventBus.emit('sellFailure', data);
    }
  }

  handleBuy(data) {
    if (this.withdraw(data.amount)) {
      this.eventBus.emit('buySuccess', data);
    } else {
      this.eventBus.emit('buyFailure', data);
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { apple: 2, banana: 3, orange: 1 };
    this.eventBus.subscribe('sellItem', this.handleSellItem.bind(this));
    this.eventBus.subscribe('buyItem', this.handleBuyItem.bind(this));
  }

  sellItem(item, amount) {
    const price = this.prices[item];
    if (price) {
      this.eventBus.emit('sell', { item, amount: price * amount });
    } else {
      console.log(`Item ${item} not found in market.`);
    }
  }

  buyItem(item, amount) {
    const price = this.prices[item];
    if (price) {
      this.eventBus.emit('buy', { item, amount: price * amount });
    } else {
      console.log(`Item ${item} not found in market.`);
    }
  }

  handleSellItem(data) {
    this.eventBus.emit('sellSuccess', data);
  }

  handleBuyItem(data) {
    this.eventBus.emit('buySuccess', data);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { apple: 0, banana: 0, orange: 0 };
    this.eventBus.subscribe('sellSuccess', this.handleSellSuccess.bind(this));
    this.eventBus.subscribe('buySuccess', this.handleBuySuccess.bind(this));
  }

  addItem(item, amount) {
    if (this.items[item] !== undefined) {
      this.items[item] += amount;
      console.log(`Added ${amount} ${item}(s), Total: ${this.items[item]}`);
    } else {
      console.log(`Item ${item} not found in inventory.`);
    }
  }

  removeItem(item, amount) {
    if (this.items[item] !== undefined && this.items[item] >= amount) {
      this.items[item] -= amount;
      console.log(`Removed ${amount} ${item}(s), Remaining: ${this.items[item]}`);
    } else {
      console.log(`Insufficient ${item}(s) in inventory.`);
    }
  }

  handleSellSuccess(data) {
    this.removeItem(data.item, 1);
  }

  handleBuySuccess(data) {
    this.addItem(data.item, 1);
  }
}

