class Pricing {
  constructor() {
    this.prices = {};
  }

  setPrice(product, price) {
    this.prices[product] = price;
  }

  getPrice(product) {
    return this.prices[product] || 0;
  }
}

class Demand {
  constructor() {
    this.demandLevels = {};
  }

  setDemand(product, level) {
    this.demandLevels[product] = level;
  }

  getDemand(product) {
    return this.demandLevels[product] || 0;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct(product, quantity) {
    const price = this.pricing.getPrice(product);
    const demand = this.demand.getDemand(product);

    if (quantity > demand) {
      console.log(`Not enough demand for ${product}. Only ${demand} available.`);
      return 0;
    }

    const revenue = price * quantity;
    this.demand.setDemand(product, demand - quantity);
    return revenue;
  }
}

