        return this.items.map(item => item.toString()).join('\n');
    }
}

class Economy {
    constructor() {
        this.balance = 1000;
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }
}

class Store {
    constructor(economy) {
        this.economy = economy;
        this.rarityTable = new RarityTable();
        this.inventory = new Inventory();
    }

