class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipe.added', this.onRecipeAdded.bind(this));
    this.eventBus.subscribe('inventory.item.removed', this.onItemRemoved.bind(this));
  }

  craft(recipeName) {
    this.eventBus.emit('crafting.attempt', { recipeName });
  }

  onRecipeAdded({ recipeName, ingredients }) {
    console.log(`Recipe "${recipeName}" added with ingredients: ${Object.keys(ingredients).join(', ')}`);
  }

  onItemRemoved({ itemName }) {
    console.log(`Item "${itemName}" removed from inventory.`);
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {};
    this.eventBus.subscribe('crafting.attempt', this.onCraftingAttempt.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
    this.eventBus.emit('recipe.added', { recipeName: name, ingredients });
  }

  onCraftingAttempt({ recipeName }) {
    if (this.recipes[recipeName]) {
      console.log(`Crafting "${recipeName}"...`);
      this.eventBus.emit('recipe.crafted', { recipeName, ingredients: this.recipes[recipeName] });
    } else {
      console.log(`Recipe "${recipeName}" not found.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('recipe.crafted', this.onRecipeCrafted.bind(this));
  }

  addItem(itemName, quantity) {
    if (!this.items[itemName]) {
      this.items[itemName] = 0;
    }
    this.items[itemName] += quantity;
    console.log(`Added ${quantity} of "${itemName}" to inventory.`);
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      this.eventBus.emit('inventory.item.removed', { itemName });
      console.log(`Removed ${quantity} of "${itemName}" from inventory.`);
    } else {
      console.log(`Not enough "${itemName}" in inventory.`);
    }
  }

  onRecipeCrafted({ recipeName, ingredients }) {
    for (const [itemName, quantity] of Object.entries(ingredients)) {
      this.removeItem(itemName, quantity);
    }
    console.log(`Crafted "${recipeName}".`);
  }
}

