class Skill {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.skills = {};
        this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
    }

    learn(skillName, level) {
        this.skills[skillName] = level;
        console.log(`Learned ${skillName} at level ${level}`);
        this.eventBus.emit('skillLearned', { skillName, level });
    }

    onLevelUp(data) {
        const { level } = data;
        for (let skill in this.skills) {
            this.skills[skill] += level;
            console.log(`Skill ${skill} advanced to level ${this.skills[skill]}`);
        }
    }
}

class Experience {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.experiencePoints = 0;
        this.eventBus.subscribe('skillLearned', this.onSkillLearned.bind(this));
    }

    gainExperience(points) {
        this.experiencePoints += points;
        console.log(`Gained ${points} experience points, total: ${this.experiencePoints}`);
        if (this.experiencePoints >= 100) {
            const levelsGained = Math.floor(this.experiencePoints / 100);
            this.experiencePoints %= 100;
            this.eventBus.emit('levelUp', { level: levelsGained });
        }
    }

    onSkillLearned(data) {
        const { skillName, level } = data;
        const points = level * 10;
        this.gainExperience(points);
    }
}

class LevelUp {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.level = 1;
        this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
    }

    onLevelUp(data) {
        const { level } = data;
        this.level += level;
        console.log(`Leveled up to level ${this.level}`);
    }
}

