class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      this.eventBus.emit('balanceChanged', this.balance);
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      this.eventBus.emit('balanceChanged', this.balance);
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
    } else {
      console.log('Invalid withdrawal amount');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      const totalCost = this.prices[item] * quantity;
      this.eventBus.emit('withdraw', totalCost);
      console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
    } else {
      console.log('Invalid item or quantity');
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('received', this.receive.bind(this));
  }

  receive(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      console.log(`Received ${quantity} ${item}(s), total: ${this.items[item]}`);
    } else {
      console.log('Invalid quantity');
    }
  }
}

