  }

  listItems() {
    console.log('Inventory contents:');
    this.items.forEach((item, index) => {
      console.log(`${index + 1}. ${item.getDetails()}`);
    });
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  generateLoot() {
    const rarity = this.rarityTable.rollRarity();
    let lootValue = 0;
    switch (rarity) {
      case 'common':
        lootValue = Math.floor(Math.random() * 10) + 1;
        break;
      case 'uncommon':
        lootValue = Math.floor(Math.random() * 20) + 10;
        break;
      case 'rare':
        lootValue = Math.floor(Math.random() * 30) + 30;
        break;
      case 'epic':
        lootValue = Math.floor(Math.random() * 40) + 60;
        break;
      case 'legendary':
        lootValue = Math.floor(Math.random() * 50) + 100;
        break;
    }
    const loot = new Loot(`Loot-${rarity.charAt(0).toUpperCase() + rarity.slice(1)}`, lootValue);
    this.inventory.addItem(loot);
  }

  displayInventory() {
    this.inventory.listItems();
  }
}

// Runnable demo
