    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;

    this.eventBus.subscribe('sellItem', ({ price }) => {
      this.deposit(price);
    });

    this.eventBus.subscribe('buyItem', ({ price }) => {
      this.withdraw(price);
    });
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
    }
  }
}

class Market {
  constructor(eventBus) {
    this.prices = {};
    this.eventBus = eventBus;

    this.eventBus.subscribe('setItemPrice', ({ item, price }) => {
      this.setPrice(item, price);
    });

    this.eventBus.subscribe('sellItem', ({ item, quantity }) => {
      this.sellItem(item, quantity);
    });

    this.eventBus.subscribe('buyItem', ({ item, quantity }) => {
      this.buyItem(item, quantity);
    });
  }

  setPrice(item, price) {
    this.prices[item] = price;
    console.log(`Set price for ${item} to ${price}`);
  }

  sellItem(item, quantity) {
    if (this.prices[item] !== undefined) {
      const total = this.prices[item] * quantity;
      this.eventBus.emit('sellItem', { price: total });
      console.log(`Sold ${quantity} of ${item} for ${total}`);
    } else {
      console.log(`Price for ${item} is not set`);
    }
  }

  buyItem(item, quantity) {
    if (this.prices[item] !== undefined) {
      const total = this.prices[item] * quantity;
      this.eventBus.emit('buyItem', { price: total });
      console.log(`Bought ${quantity} of ${item} for ${total}`);
    } else {
      console.log(`Price for ${item} is not set`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;

    this.eventBus.subscribe('sellItem', ({ item, quantity }) => {
      this.removeItem(item, quantity);
    });

    this.eventBus.subscribe('buyItem', ({ item, quantity }) => {
      this.addItem(item, quantity);
    });
  }

  addItem(item, quantity) {
    if (this.items[item] === undefined) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    console.log(`Added ${quantity} of ${item}. Total: ${this.items[item]}`);
  }

  removeItem(item, quantity) {
    if (this.items[item] !== undefined && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} of ${item}. Total: ${this.items[item]}`);
    } else {
      console.log(`Insufficient ${item} in inventory`);
    }
  }
}

