class Crop {
  constructor(name, growthRate) {
    this.name = name;
    this.growthRate = growthRate;
    this.stage = 0;
  }

  grow() {
    this.stage = Math.min(this.stage + this.growthRate, 5); // 5 is the max stage
    return this.stage;
  }

  isReady() {
    return this.stage === 5;
  }

  toString() {
    return `${this.name} (Stage: ${this.stage})`;
  }
}

class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  growCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestReadyCrops() {
    return this.crops.filter(crop => crop.isReady()).map(crop => crop.name);
  }

  toString() {
    return `Farm: ${this.crops.map(crop => crop.toString()).join(', ')}`;
  }
}

class Market {
  constructor(store, economy) {
    this.store = store;
    this.economy = economy;
  }

  buyCrop(cropName) {
    const price = this.economy.getPrice(cropName);
    if (price !== null && this.economy.debit(price)) {
      this.store.addItem(cropName);
      return true;
    }
    return false;
  }

  toString() {
    return `Market: Prices - ${Object.entries(this.economy.prices).map(([crop, price]) => `${crop}: ${price}`).join(', ')}`;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices;
    this.balance = 100; // Initial balance
  }

  getPrice(cropName) {
    return this.prices[cropName] || null;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  toString() {
    return `Economy: Balance - ${this.balance}, Prices - ${Object.entries(this.prices).map(([crop, price]) => `${crop}: ${price}`).join(', ')}`;
  }
}

class Store {
  constructor() {
    this.inventory = {};
  }

  addItem(cropName) {
    if (this.inventory[cropName]) {
      this.inventory[cropName]++;
    } else {
      this.inventory[cropName] = 1;
    }
  }

  toString() {
    return `Store: Inventory - ${Object.entries(this.inventory).map(([crop, quantity]) => `${crop}: ${quantity}`).join(', ')}`;
  }
}

