    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequest', this.onCraftRequest.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  craft(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      this.eventBus.emit('craftRequest', { recipeName, ingredients });
    } else {
      console.log(`Recipe not found: ${recipeName}`);
    }
  }

  onCraftRequest({ recipeName, ingredients }) {
