class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftAttempt', this.onCraftAttempt.bind(this));
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemRemoved', this.onItemRemoved.bind(this));
  }

  onCraftAttempt({ recipeName, ingredients }) {
    const canCraft = Object.keys(ingredients).every(item => {
      return this.eventBus.emit('checkInventory', { item, quantity: ingredients[item] });
    });

    if (canCraft) {
      Object.keys(ingredients).forEach(item => {
        this.eventBus.emit('itemRemoved', { item, quantity: ingredients[item] });
      });
      this.eventBus.emit('itemAdded', { item: recipeName, quantity: 1 });
      console.log(`Crafting: Successfully crafted ${recipeName}`);
    } else {
      console.log(`Crafting: Failed to craft ${recipeName} due to insufficient ingredients`);
    }
  }

  onItemAdded({ item, quantity }) {
    console.log(`Crafting: Item added to inventory - ${item}: ${quantity}`);
  }

  onItemRemoved({ item, quantity }) {
    console.log(`Crafting: Item removed from inventory - ${item}: ${quantity}`);
  }
}

