// Wallet System
class Wallet {
  constructor(initialBalance = 0) {
    this._balance = initialBalance;
  }

  getBalance() {
    return this._balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this._balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this._balance >= amount) {
      this._balance -= amount;
      return true;
    }
    return false;
  }
}

// Shop System
class Shop {
  constructor() {
    this._items = {
      sword: { price: 100 },
      shield: { price: 75 },
      potion: { price: 50 }
    };
  }

  getItemPrice(item) {
    return this._items[item]?.price || 0;
  }

  sellItem(item, wallet) {
    const price = this.getItemPrice(item);
    if (wallet.withdraw(price)) {
      console.log(`Sold ${item} for ${price} gold.`);
      return true;
    }
    console.log(`Insufficient funds to buy ${item}.`);
    return false;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this._items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this._items[item] = (this._items[item] || 0) + quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this._items[item] >= quantity) {
      this._items[item] -= quantity;
      if (this._items[item] === 0) {
        delete this._items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this._items };
  }
}

