  }
}

class RarityTable {
  constructor() {
    this.rarityMap = {
      "common": 0.6,
      "uncommon": 0.3,
      "rare": 0.05,
      "epic": 0.03,
      "legendary": 0.02
    };
  }

  getRarity(item) {
    const random = Math.random();
    let cumulativeProbability = 0;
    for (const [rarity, probability] of Object.entries(this.rarityMap)) {
      cumulativeProbability += probability;
      if (random < cumulativeProbability) {
        return rarity;
      }
    }
    return "common"; // Fallback to common if probabilities are misconfigured
  }
}

class Inventory {
