class TradeSystem {
  constructor() {
    this.trades = [];
  }

  recordTrade(participants, resources) {
    this.trades.push({ participants, resources });
  }

  getTradeHistory() {
    return this.trades;
  }
}

class ReputationSystem {
  constructor() {
    this.reputations = {};
  }

  updateReputation(entity, change) {
    if (!this.reputations[entity]) {
      this.reputations[entity] = 0;
    }
    this.reputations[entity] += change;
  }

  getReputation(entity) {
    return this.reputations[entity] || 0;
  }
}

class FactionSystem {
  constructor(tradeSystem, reputationSystem) {
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
    this.factions = {};
  }

  joinFaction(entity, faction) {
    if (!this.factions[faction]) {
      this.factions[faction] = new Set();
    }
    this.factions[faction].add(entity);
  }

  performTrade(entity, faction, resources) {
    if (this.factions[faction] && this.factions[faction].has(entity)) {
      this.tradeSystem.recordTrade([entity, faction], resources);
      this.reputationSystem.updateReputation(faction, 1);
    }
  }

  getFactionMembers(faction) {
    return this.factions[faction] ? Array.from(this.factions[faction]) : [];
  }
}

