class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(eventName, listener) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(listener);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.handleDeposit.bind(this));
    this.eventBus.subscribe('withdraw', this.handleWithdraw.bind(this));
  }

  deposit(amount) {
    this.eventBus.emit('deposit', amount);
  }

  withdraw(amount) {
    this.eventBus.emit('withdraw', amount);
  }

  handleDeposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  handleWithdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Insufficient funds');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { apple: 1, banana: 2, orange: 3 };
    this.eventBus.subscribe('buy', this.handleBuy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price) {
      const totalCost = price * quantity;
      this.eventBus.emit('buy', { item, quantity, totalCost });
    } else {
      console.log('Item not found');
    }
  }

  handleBuy({ item, quantity, totalCost }) {
    console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
    this.eventBus.emit('withdraw', totalCost);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { apple: 0, banana: 0, orange: 0 };
    this.eventBus.subscribe('buy', this.handleBuy.bind(this));
  }

  handleBuy({ item, quantity }) {
    if (this.items[item] !== undefined) {
      this.items[item] += quantity;
      console.log(`Inventory updated: ${item} - ${this.items[item]}`);
    } else {
      console.log('Item not found in inventory');
    }
  }
}

