  constructor(skill, experience) {
    this.skill = skill;
    this.experience = experience;
    this.levelThresholds = [10, 20, 30]; // Example thresholds for level 1, 2, 3
  }

  checkLevelUp() {
    const currentExperience = this.experience.getTotalExperience();
    const currentLevel = this.skill.getLevel();

    for (let i = 0; i < this.levelThresholds.length; i++) {
      if (currentExperience >= this.levelThresholds[i] && currentLevel <= i + 1) {
        this.skill.improve();
        this.levelThresholds[i] *= 2; // Example: double the threshold for next level
        console.log(`Reached level ${currentLevel + 1}!`);
      }
    }
  }
}

