class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  handlePurchase(data) {
    const { cost } = data;
    if (this.balance >= cost) {
      this.balance -= cost;
      console.log(`Purchased ${data.item} for ${cost}. New balance: ${this.balance}`);
      this.eventBus.emit('purchased', data);
    } else {
      console.log(`Insufficient funds to purchase ${data.item}. Current balance: ${this.balance}`);
    }
  }
}

