  coordinator.growCrops();
}

// Harvest and sell crops
coordinator.harvestAndSell();

// Check market inventory
console.log('Market Inventory:', coordinator.getMarketInventory());
// Expected output: Market Inventory: { Wheat: 1, Corn: 1 }
