class Order {
  constructor() {
    this.orders = [];
  }

  placeOrder(item) {
    const orderId = this.orders.length + 1;
    this.orders.push({ orderId, item, status: 'placed' });
    console.log(`Order ${orderId} for ${item} placed.`);
    return orderId;
  }

  getOrderStatus(orderId) {
    const order = this.orders.find(o => o.orderId === orderId);
    if (order) {
      return order.status;
    } else {
      throw new Error(`Order ${orderId} not found.`);
    }
  }

  updateOrderStatus(orderId, status) {
    const order = this.orders.find(o => o.orderId === orderId);
    if (order) {
      order.status = status;
      console.log(`Order ${orderId} status updated to ${status}.`);
    } else {
      throw new Error(`Order ${orderId} not found.`);
    }
  }
}

class Kitchen {
  constructor(orderSystem) {
    this.orderSystem = orderSystem;
  }

  startCooking(orderId) {
    try {
      const status = this.orderSystem.getOrderStatus(orderId);
      if (status === 'placed') {
        console.log(`Starting to cook order ${orderId}.`);
        this.orderSystem.updateOrderStatus(orderId, 'cooking');
      } else {
        console.log(`Order ${orderId} is already ${status}, cannot start cooking.`);
      }
    } catch (error) {
      console.error(error.message);
    }
  }

  finishCooking(orderId) {
    try {
      const status = this.orderSystem.getOrderStatus(orderId);
      if (status === 'cooking') {
        console.log(`Finished cooking order ${orderId}.`);
        this.orderSystem.updateOrderStatus(orderId, 'cooked');
      } else {
        console.log(`Order ${orderId} is already ${status}, cannot finish cooking.`);
      }
    } catch (error) {
      console.error(error.message);
    }
  }
}

class Customer {
  constructor(orderSystem, kitchenSystem) {
    this.orderSystem = orderSystem;
    this.kitchenSystem = kitchenSystem;
  }

  placeOrder(item) {
    const orderId = this.orderSystem.placeOrder(item);
    this.kitchenSystem.startCooking(orderId);
    return orderId;
  }

  checkOrderStatus(orderId) {
    try {
      const status = this.orderSystem.getOrderStatus(orderId);
      console.log(`Order ${orderId} status: ${status}.`);
      return status;
    } catch (error) {
      console.error(error.message);
      return null;
    }
  }
}

// Top-level coordinator
class Restaurant {
  constructor() {
    this.orderSystem = new Order();
    this.kitchenSystem = new Kitchen(this.orderSystem);
    this.customerSystem = new Customer(this.orderSystem, this.kitchenSystem);
  }

  runDemo() {
    const orderId = this.customerSystem.placeOrder('burger');
    this.customerSystem.checkOrderStatus(orderId);
    this.kitchenSystem.finishCooking(orderId);
    this.customerSystem.checkOrderStatus(orderId);
  }
}

