class Bank {
    constructor(eventBus) {
        this.balance = 0;
        this.eventBus = eventBus;
        this.eventBus.subscribe('sellItem', this.onSellItem.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds. Current balance: ${this.balance}`);
            return false;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
        return true;
    }

    onSellItem(data) {
        if (this.withdraw(data.price)) {
            console.log(`Item sold for ${data.price}`);
            this.eventBus.emit('itemSold', data.item);
        }
    }
}

class Market {
    constructor(eventBus) {
        this.items = [];
        this.eventBus = eventBus;
        this.eventBus.subscribe('itemSold', this.onItemSold.bind(this));
    }

    addItem(item, price) {
        this.items.push({ item, price });
        console.log(`Added item: ${item} for price: ${price}`);
    }

    sellItem(item) {
        const itemToSell = this.items.find(i => i.item === item);
        if (itemToSell) {
            console.log(`Selling item: ${item} for price: ${itemToSell.price}`);
            this.eventBus.emit('sellItem', itemToSell);
        } else {
            console.log(`Item not found: ${item}`);
        }
    }

    onItemSold(item) {
        console.log(`Market received sold item: ${item}`);
        this.items = this.items.filter(i => i.item !== item);
    }
}

class Inventory {
    constructor(eventBus) {
        this.items = [];
        this.eventBus = eventBus;
    }

    addItem(item) {
        this.items.push(item);
        console.log(`Added to inventory: ${item}`);
    }

    removeItem(item) {
        const index = this.items.indexOf(item);
        if (index !== -1) {
            this.items.splice(index, 1);
            console.log(`Removed from inventory: ${item}`);
        } else {
            console.log(`Item not found in inventory: ${item}`);
        }
    }
}

