class RarityTable {
  constructor() {
    this.rarityLevels = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
    this.weights = [0.5, 0.3, 0.1, 0.05, 0.05];
  }

  getRandomRarity() {
    const totalWeight = this.weights.reduce((acc, weight) => acc + weight, 0);
    let random = Math.random() * totalWeight;
    for (let i = 0; i < this.rarityLevels.length; i++) {
      if (random < this.weights[i]) {
        return this.rarityLevels[i];
      }
      random -= this.weights[i];
    }
    return this.rarityLevels[this.rarityLevels.length - 1]; // Fallback
  }
}

