    this.items = {
      bread: 10,
      milk: 5,
      apple: 3
    };
    this.prices = {
      bread: 2,
      milk: 3,
      apple: 1
    };
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }

  buyItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.stock = {};
  }

  addItem(item, quantity) {
    if (this.stock[item]) {
      this.stock[item] += quantity;
    } else {
      this.stock[item] = quantity;
    }
  }

  getStock(item) {
    return this.stock[item] || 0;
  }
}

