    this.prices = prices; // { item: price }
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price !== undefined && bank.withdraw(price)) {
      console.log(`Bought ${item} for ${price}`);
      return true;
    } else {
      console.log(`Could not buy ${item}`);
      return false;
    }
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price !== undefined) {
      bank.deposit(price);
      console.log(`Sold ${item} for ${price}`);
      return true;
    } else {
      console.log(`Could not sell ${item}`);
      return false;
    }
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

