class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    } else {
      throw new Error(`Not enough ${item} in inventory`);
    }
  }

  hasItems(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe objects
  }

  canCraft(recipeId) {
    const recipe = this.recipes.find(r => r.id === recipeId);
    if (!recipe) {
      throw new Error(`Recipe ${recipeId} not found`);
    }
    return this.inventory.hasItems(recipe.ingredients);
  }

  craft(recipeId) {
    if (!this.canCraft(recipeId)) {
      throw new Error(`Cannot craft ${recipeId}: missing ingredients`);
    }
    const recipe = this.recipes.find(r => r.id === recipeId);
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      this.inventory.removeItem(item, quantity);
    }
    for (const [item, quantity] of Object.entries(recipe.result)) {
      this.inventory.addItem(item, quantity);
    }
  }
}

// Demo
