inventory.addItem('wood', 10);
inventory.addItem('stone', 5);

const recipes = [
  new Recipe('stick', { wood: 1 }, { stick: 1 }),
  new Recipe('axe', { stick: 2, stone: 1 }, { axe: 1 })
];

const crafting = new Crafting(inventory, recipes);

