class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    } else {
      console.log("Deposit amount must be positive.");
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log("Invalid withdrawal amount.");
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(bank, inventory) {
    this.bank = bank;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      console.log(`Set price for ${item} to ${price}`);
    } else {
      console.log("Price must be positive.");
    }
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price && quantity > 0) {
      const totalCost = price * quantity;
      if (this.bank.getBalance() >= totalCost) {
        this.bank.withdraw(totalCost);
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
      } else {
        console.log("Insufficient funds.");
      }
    } else {
      console.log("Invalid purchase.");
    }
  }

  sell(item, quantity) {
    const price = this.prices[item];
    if (price && quantity > 0) {
      const totalRevenue = price * quantity;
      if (this.inventory.removeItem(item, quantity)) {
        this.bank.deposit(totalRevenue);
        console.log(`Sold ${quantity} ${item}(s) for ${totalRevenue}.`);
      } else {
        console.log("Insufficient inventory.");
      }
    } else {
      console.log("Invalid sale.");
    }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      console.log(`Added ${quantity} ${item}(s). Current inventory:`, this.items);
    } else {
      console.log("Quantity must be positive.");
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      console.log(`Removed ${quantity} ${item}(s). Current inventory:`, this.items);
      return true;
    } else {
      console.log("Insufficient inventory.");
      return false;
    }
  }

  getInventory() {
    return this.items;
  }
}

