class Crafting {
  constructor(recipes) {
    this.recipes = new Map();
    recipes.forEach(recipe => this.recipes.set(recipe.item, recipe));
  }

  canCraft(item, inventory) {
    const recipe = this.recipes.get(item);
    if (!recipe) return false;
    for (const [ingredient, quantity] of recipe.ingredients.entries()) {
      if (inventory.get(ingredient) < quantity) return false;
    }
    return true;
  }

  craft(item, inventory) {
    const recipe = this.recipes.get(item);
    if (!recipe) return false;
    for (const [ingredient, quantity] of recipe.ingredients.entries()) {
      inventory.set(ingredient, inventory.get(ingredient) - quantity);
    }
    inventory.set(item, (inventory.get(item) || 0) + 1);
    return true;
  }
}

