class Experience {
    constructor(skill) {
        this.skill = skill;
        this.currentExp = 0;
        this.requiredExp = 100; // Initial requirement for level up
    }

    gainExperience(amount) {
        this.currentExp += amount;
        console.log(`Gained ${amount} experience. Total: ${this.currentExp}`);
        while (this.currentExp >= this.requiredExp) {
            this.levelUp();
        }
    }

