  }
}

class GameCoordinator {
  constructor(wallet, shop, inventory) {
    this.wallet = wallet;
    this.shop = shop;
    this.inventory = inventory;
  }

  buyItem(itemId) {
    const price = this.shop.getItemPrice(itemId);
    if (price !== null && this.wallet.withdraw(price)) {
      this.inventory.addItem(itemId);
      return true;
    }
    return false;
  }

  sellItem(itemId) {
    const quantity = this.inventory.getItemCount(itemId);
    if (quantity > 0) {
      const price = this.shop.getItemPrice(itemId);
      if (price !== null) {
        this.wallet.deposit(price);
        this.inventory.removeItem(itemId);
        return true;
      }
    }
    return false;
  }

  getWalletBalance() {
    return this.wallet.getBalance();
  }

  listShopItems() {
    return this.shop.listItems();
  }

  getInventory() {
    return this.inventory.items;
  }
}

