class Loot {
  constructor(rarityTable) {
    this.rarityTable = rarityTable;
  }

  generateLoot() {
    const rarity = this.rarityTable.getRandomRarity();
    return { type: 'item', rarity };
  }
}

class RarityTable {
  constructor(rarityDistribution) {
    this.rarityDistribution = rarityDistribution;
  }

  getRandomRarity() {
    const totalWeight = Object.values(this.rarityDistribution).reduce((sum, weight) => sum + weight, 0);
    let random = Math.random() * totalWeight;
    let cumulativeWeight = 0;

    for (const [rarity, weight] of Object.entries(this.rarityDistribution)) {
      cumulativeWeight += weight;
      if (random < cumulativeWeight) {
        return rarity;
      }
    }

    return null; // Should never reach here if weights are valid
  }
}

