class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {}; // { item: quantity }
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    console.log(`Added ${quantity} ${item} to inventory.`);
  }

  hasIngredients(recipe) {
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(recipe) {
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      this.items[item] -= quantity;
    }
  }

  handleCraft(recipe) {
    if (this.hasIngredients(recipe)) {
      this.consumeIngredients(recipe);
      this.addItem(recipe.result.item, recipe.result.quantity);
      console.log(`Crafted ${recipe.result.quantity} ${recipe.result.item}.`);
    } else {
      console.log(`Not enough ingredients to craft ${recipe.name}.`);
    }
  }
}

class Crafting {
