      this.inventory[crop.name].quantity++;
    } else {
      this.inventory[crop.name] = { crop, quantity: 1, price };
    }
    console.log(`Bought a ${crop.name} crop for $${price}.`);
  }

  sellCrop(cropName) {
    if (this.inventory[cropName] && this.inventory[cropName].quantity > 0) {
      this.inventory[cropName].quantity--;
      console.log(`Sold a ${cropName} crop.`);
      return this.inventory[cropName].price;
    } else {
      console.log(`No ${cropName} crops available to sell.`);
      return 0;
