// Crafting System
class Crafting {
  constructor() {
    this.recipes = new Map();
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.name, recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;
    for (const [item, requiredAmount] of Object.entries(recipe.ingredients)) {
      if (inventory.countItem(item) < requiredAmount) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (!this.canCraft(recipeName, inventory)) {
      throw new Error(`Cannot craft ${recipeName}: insufficient resources.`);
    }
    const recipe = this.recipes.get(recipeName);
    for (const [item, requiredAmount] of Object.entries(recipe.ingredients)) {
      inventory.removeItem(item, requiredAmount);
    }
    inventory.addItem(recipe.result, recipe.resultAmount);
  }
}

// Recipe System
class Recipe {
  constructor(name, ingredients, result, resultAmount) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: amount }
    this.result = result;
    this.resultAmount = resultAmount;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, amount = 1) {
    this.items.set(item, (this.items.get(item) || 0) + amount);
  }

  removeItem(item, amount = 1) {
    if (!this.items.has(item)) throw new Error(`Item ${item} not found.`);
    if (this.items.get(item) < amount) throw new Error(`Not enough ${item} to remove.`);
    this.items.set(item, this.items.get(item) - amount);
    if (this.items.get(item) === 0) this.items.delete(item);
  }

  countItem(item) {
    return this.items.get(item) || 0;
  }

  listItems() {
    return Array.from(this.items.entries());
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    this.crafting = new Crafting();
    this.inventory = new Inventory();
  }

  addRecipe(recipe) {
    this.crafting.addRecipe(recipe);
  }

  craftItem(recipeName) {
    try {
      this.crafting.craft(recipeName, this.inventory);
      console.log(`Crafted ${recipeName}`);
