class Trade {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  buy(resource, amount, pricePerUnit) {
    if (this.resources.gold >= amount * pricePerUnit) {
      this.resources.gold -= amount * pricePerUnit;
      this.resources[resource] += amount;
      return true;
    }
    return false;
  }

  sell(resource, amount, pricePerUnit) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      this.resources.gold += amount * pricePerUnit;
      return true;
    }
    return false;
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  tradeSuccess() {
    this.standing += 5;
  }

  tradeFailure() {
    this.standing -= 5;
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor(name) {
    this.name = name;
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  receiveResources(resources) {
    for (const [resource, amount] of Object.entries(resources)) {
      this.resources[resource] += amount;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Coordinator {
  constructor() {
    this.trade = new Trade();
    this.reputation = new Reputation();
    this.faction = new Faction("Woodcutters");
  }

  performTrade(resource, amount, pricePerUnit) {
    if (this.trade.buy(resource, amount, pricePerUnit)) {
      this.reputation.tradeSuccess();
      this.faction.receiveResources({ [resource]: amount });
      console.log(`Trade successful. Bought ${amount} ${resource}.`);
    } else {
      this.reputation.tradeFailure();
      console.log(`Trade failed. Not enough gold.`);
    }
  }

  checkStatus() {
    console.log("Trade Resources:", this.trade.getResources());
    console.log("Reputation Standing:", this.reputation.getStanding());
    console.log("Faction Resources:", this.faction.getResources());
  }
}

