class Building {
  constructor(name, initialCapacity) {
    this.name = name;
    this.capacity = initialCapacity;
    this.occupied = 0;
  }

  // Public API
  build(quantity) {
    if (this.occupied + quantity <= this.capacity) {
      this.occupied += quantity;
      return true;
    }
    return false;
  }

  getOccupied() {
    return this.occupied;
  }

  getCapacity() {
    return this.capacity;
  }
}

class Resource {
  constructor(name, initialAmount) {
    this.name = name;
    this.amount = initialAmount;
  }

  // Public API
  consume(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  produce(amount) {
    this.amount += amount;
  }

  getAmount() {
    return this.amount;
  }
}

class Economy {
  constructor() {
    this.resources = {};
  }

  // Public API
  registerResource(name, initialAmount) {
    this.resources[name] = new Resource(name, initialAmount);
  }

  consumeResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].consume(amount);
    }
    return false;
  }

  produceResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      this.resources[resourceName].produce(amount);
      return true;
    }
    return false;
  }

  getResourceAmount(resourceName) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].getAmount();
    }
    return 0;
  }
}

// Top-level coordinator
