  constructor() {
    this.prices = new Map();
  }

  setPrice(product, price) {
    this.prices.set(product, price);
  }

  getPrice(product) {
    return this.prices.get(product) || 0;
  }
}

class Demand {
  constructor(pricing) {
    this.pricing = pricing;
    this.demands = new Map();
  }

  setDemand(product, demand) {
    this.demands.set(product, demand);
  }

  getDemand(product) {
    return this.demands.get(product) || 0;
  }

  calculateRevenue(product) {
    const price = this.pricing.getPrice(product);
    const demand = this.getDemand(product);
    return price * demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = new Map();
  }

  restock(product, quantity) {
    this.inventory.set(product, (this.inventory.get(product) || 0) + quantity);
  }

  sell(product, quantity) {
    if (this.inventory.get(product) >= quantity) {
      this.inventory.set(product, this.inventory.get(product) - quantity);
      return true;
    }
    return false;
  }

  getInventory(product) {
    return this.inventory.get(product) || 0;
  }

  calculateTotalRevenue() {
    let totalRevenue = 0;
    for (const product of this.inventory.keys()) {
      totalRevenue += this.demand.calculateRevenue(product);
    }
    return totalRevenue;
  }
}

