class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Shop {
  constructor(wallet) {
    this.wallet = wallet;
    this.items = {
      apple: 1,
      bread: 2,
      milk: 3
    };
  }

  buy(item) {
    const price = this.items[item];
    if (price === undefined) {
      throw new Error("Item not available");
    }
    this.wallet.withdraw(price);
    return item;
  }

  getPrice(item) {
    return this.items[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

