class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(itemName, quantity) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
    }
  }

  hasIngredients(ingredients) {
    for (const [itemName, quantity] of Object.entries(ingredients)) {
      if (!this.items[itemName] || this.items[itemName] < quantity) {
        return false;
      }
    }
    return true;
  }

  getInventory() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // { recipeName: Recipe }
  }

  addRecipe(recipe) {
    this.recipes[recipe.getName()] = recipe;
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) {
      console.log(`Recipe "${recipeName}" not found.`);
      return false;
    }

    const ingredients = recipe.getIngredients();
    if (!this.inventory.hasIngredients(ingredients)) {
      console.log(`Missing ingredients for "${recipeName}".`);
      return false;
    }

    for (const [itemName, quantity] of Object.entries(ingredients)) {
      this.inventory.removeItem(itemName, quantity);
    }

    console.log(`Crafted "${recipeName}".`);
    return true;
  }

  getRecipes() {
    return Object.keys(this.recipes);
  }
}

