class Economy {
  constructor() {
    this.balances = {};
  }

  getBalance(playerId) {
    return this.balances[playerId] || 0;
  }

  debit(playerId, amount) {
    if (this.balances[playerId] === undefined) {
      this.balances[playerId] = 0;
    }
    if (this.balances[playerId] >= amount) {
      this.balances[playerId] -= amount;
      return true;
    }
    return false;
  }

  credit(playerId, amount) {
    if (this.balances[playerId] === undefined) {
      this.balances[playerId] = 0;
    }
    this.balances[playerId] += amount;
  }
}

class Loot {
  constructor() {
    this.lootTable = {};
  }

  addItem(item, rarity) {
    if (!this.lootTable[rarity]) {
      this.lootTable[rarity] = [];
    }
    this.lootTable[rarity].push(item);
  }

  getRandomItem(rarity) {
    const items = this.lootTable[rarity];
    if (items && items.length > 0) {
      const randomIndex = Math.floor(Math.random() * items.length);
      return items[randomIndex];
    }
    return null;
  }
}

class RarityTable {
  constructor() {
    this.table = {};
  }

  addRarity(rarity, weight) {
    this.table[rarity] = weight;
  }

  getRandomRarity() {
    const rarities = Object.keys(this.table);
    let totalWeight = 0;
    rarities.forEach(rarity => {
      totalWeight += this.table[rarity];
    });

    const randomWeight = Math.random() * totalWeight;
    let cumulativeWeight = 0;
    for (const rarity of rarities) {
      cumulativeWeight += this.table[rarity];
      if (randomWeight <= cumulativeWeight) {
        return rarity;
      }
    }
    return null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item]++;
  }

  getItems() {
    return this.items;
  }
}

class Store {
  constructor(economy, loot, rarityTable) {
    this.economy = economy;
    this.loot = loot;
    this.rarityTable = rarityTable;
    this.prices = {
      common: 10,
      uncommon: 20,
      rare: 30,
      epic: 40,
      legendary: 50
    };
  }

  purchaseItem(playerId) {
    const rarity = this.rarityTable.getRandomRarity();
    const item = this.loot.getRandomItem(rarity);
    const price = this.prices[rarity] || 0;

    if (this.economy.debit(playerId, price)) {
      this.inventory.addItem(item);
      console.log(`Player ${playerId} purchased ${item} (${rarity}) for ${price} gold.`);
      return true;
    } else {
      console.log(`Player ${playerId} does not have enough gold to purchase ${item} (${rarity}).`);
      return false;
    }
  }

  setInventory(inventory) {
    this.inventory = inventory;
  }
}

