class EventBus {
  constructor() {
    this.events = {};
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(handler => handler(data));
    }
  }

  subscribe(event, handler) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(handler);
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('product-sold', this.updatePrice.bind(this));
    this.prices = {
      'productA': 10,
      'productB': 20,
      'productC': 30
    };
  }

  updatePrice(data) {
    const { product, quantity } = data;
    if (this.prices[product] && quantity > 10) {
      this.prices[product] *= 0.9; // Apply a 10% discount for bulk purchase
    }
    console.log(`Updated price for ${product}: $${this.prices[product]}`);
  }

  getPrice(product) {
    return this.prices[product] || 0;
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('product-sold', this.updateDemand.bind(this));
    this.demand = {
      'productA': 100,
      'productB': 150,
      'productC': 200
    };
  }

  updateDemand(data) {
    const { product, quantity } = data;
    if (this.demand[product]) {
      this.demand[product] -= quantity;
    }
    console.log(`Remaining demand for ${product}: ${this.demand[product]}`);
  }

  getDemand(product) {
    return this.demand[product] || 0;
  }
}

class Store {
  constructor(eventBus, pricing, demand) {
    this.eventBus = eventBus;
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct(product, quantity) {
    if (this.demand.getDemand(product) >= quantity) {
      this.eventBus.emit('product-sold', { product, quantity });
      console.log(`Sold ${quantity} of ${product} at $${this.pricing.getPrice(product)}`);
    } else {
      console.log(`Insufficient demand for ${product}`);
    }
  }
}

