    this.rarityMap = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      legendary: 0.02
    };

    this.eventBus.subscribe('generateLoot', this.handleGenerateLoot.bind(this));
  }

  handleGenerateLoot() {
    const roll = Math.random();
    let rarity;
    if (roll < this.rarityMap.common) {
      rarity = 'common';
    } else if (roll < this.rarityMap.common + this.rarityMap.uncommon) {
      rarity = 'uncommon';
    } else if (roll < this.rarityMap.common + this.rarityMap.uncommon + this.rarityMap.rare) {
      rarity = 'rare';
    } else {
      rarity = 'legendary';
    }
    this.eventBus.emit('lootGenerated', { rarity });
  }
}

