    getItemQuantity(itemName) {
        return this.items[itemName]?.quantity || 0;
    }

    sellItem(itemName, quantity, economy) {
        const item = this.items[itemName];
        if (item && item.quantity >= quantity && economy.withdraw(item.price * quantity)) {
            item.quantity -= quantity;
            return true;
        }
        return false;
    }
