class Economy {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        this.balance += amount;
        return this.balance;
    }

    withdraw(amount) {
        if (amount > this.balance) {
            return false;
        }
        this.balance -= amount;
        return true;
    }

    getBalance() {
        return this.balance;
    }
}

class Store {
    constructor(prices) {
        this.prices = prices;
    }

    getItemPrice(item) {
        return this.prices[item] || null;
    }

    listItems() {
        return Object.keys(this.prices);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (!this.items[item] || this.items[item] < quantity) {
            return false;
        }
        this.items[item] -= quantity;
        if (this.items[item] === 0) {
            delete this.items[item];
        }
        return true;
    }

    getInventory() {
        return { ...this.items };
    }
}

