class RarityTable {
    constructor() {
        this.table = [
            { rarity: 'Common', chance: 0.7 },
            { rarity: 'Uncommon', chance: 0.2 },
            { rarity: 'Rare', chance: 0.08 },
            { rarity: 'Epic', chance: 0.02 }
        ];
    }

    getRandomLoot() {
        const random = Math.random();
        let cumulativeChance = 0;

        for (const entry of this.table) {
            cumulativeChance += entry.chance;
            if (random <= cumulativeChance) {
                return new Loot(`Loot of ${entry.rarity}`, this.getValueForRarity(entry.rarity));
            }
        }

        throw new Error('Failed to generate loot');
    }

    getValueForRarity(rarity) {
        switch (rarity) {
            case 'Common':
                return Math.floor(Math.random() * 10) + 1;
            case 'Uncommon':
                return Math.floor(Math.random() * 20) + 10;
            case 'Rare':
                return Math.floor(Math.random() * 50) + 30;
            case 'Epic':
                return Math.floor(Math.random() * 100) + 80;
            default:
                throw new Error('Unknown rarity');
        }
    }
}

class Inventory {
