// Trade System
class TradeSystem {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  trade(resource, amount, price) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      this.resources.gold += price;
      return true;
    }
    return false;
  }

  getResources() {
    return { ...this.resources };
  }
}

// Reputation System
class ReputationSystem {
  constructor() {
    this.reputation = 50;
  }

  modifyReputation(amount) {
    this.reputation += amount;
    if (this.reputation < 0) this.reputation = 0;
    if (this.reputation > 100) this.reputation = 100;
  }

  getReputation() {
    return this.reputation;
  }
}

// Faction System
class FactionSystem {
  constructor() {
    this.factions = { traders: 50, warriors: 50 };
  }

  influenceFaction(faction, amount) {
    if (this.factions[faction] !== undefined) {
      this.factions[faction] += amount;
      if (this.factions[faction] < 0) this.factions[faction] = 0;
      if (this.factions[faction] > 100) this.factions[faction] = 100;
    }
  }

  getFactions() {
    return { ...this.factions };
  }
}

// Coordinator
class Coordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  tradeResource(resource, amount, price) {
    if (this.tradeSystem.trade(resource, amount, price)) {
      this.reputationSystem.modifyReputation(5);
      this.factionSystem.influenceFaction('traders', 5);
      return true;
    }
    return false;
  }

  displayStatus() {
    console.log('Resources:', this.tradeSystem.getResources());
    console.log('Reputation:', this.reputationSystem.getReputation());
    console.log('Factions:', this.factionSystem.getFactions());
  }
}

// Demo
const coordinator = new Coordinator();

console.log('Initial Status:');
coordinator.displayStatus();

console.log('\nTrading 10 wood for 50 gold:');
const tradeSuccess = coordinator.tradeResource('wood', 10, 50);
console.log('Trade Success:', tradeSuccess);

console.log('\nStatus after trade:');
coordinator.displayStatus();
