class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time += 1;
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class Energy {
  constructor(clock) {
    this.clock = clock;
    this.energyLevel = 100;
  }

  consume(amount) {
    if (this.energyLevel >= amount) {
      this.energyLevel -= amount;
    } else {
      this.energyLevel = 0;
    }
    console.log(`Energy consumed at time ${this.clock.getTime()}: ${amount}. Remaining: ${this.energyLevel}`);
  }

  regenerate(amount) {
    this.energyLevel += amount;
    if (this.energyLevel > 100) {
      this.energyLevel = 100;
    }
    console.log(`Energy regenerated at time ${this.clock.getTime()}: ${amount}. Current: ${this.energyLevel}`);
  }
}

class Hunger {
  constructor(clock, energy) {
    this.clock = clock;
    this.energy = energy;
    this.hungerLevel = 0;
  }

  eat(amount) {
    if (this.hungerLevel <= 100 - amount) {
      this.hungerLevel += amount;
      this.energy.regenerate(amount * 5); // Eating regenerates energy
    } else {
      this.hungerLevel = 100;
    }
    console.log(`Ate at time ${this.clock.getTime()}: ${amount}. Hunger: ${this.hungerLevel}`);
  }

  increase(amount) {
    if (this.hungerLevel >= amount) {
      this.hungerLevel -= amount;
      this.energy.consume(amount * 10); // Hunger consumes energy
    } else {
      this.hungerLevel = 0;
    }
    console.log(`Hunger increased at time ${this.clock.getTime()}: ${amount}. Hunger: ${this.hungerLevel}`);
  }
}

// Demo
const clock = new Clock();
const energy = new Energy(clock);
const hunger = new Hunger(clock, energy);

console.log("Starting simulation...");

for (let i = 0; i < 10; i++) {
  clock.tick();
  hunger.increase(5);
  if (i % 2 === 0) {
    hunger.eat(10);
  }
}

console.log("Simulation complete.");
